import { setSpriteCacheStamp } from '@/utils/spriteLoader';
import { IS_NFL } from '@/config/edition';
import { numberTables, setKitColors, setNumberTables, setSockTemplate, type KitColors } from '@/utils/kitColorTable';
import { useSyncExternalStore } from 'react';
import type * as SpriteArt from './gameSpriteArt';
import { findNFLTeam } from './nflTeams';
import { dataResponse } from '@/utils/dataStore';
import { resolveSuffixKey } from '@/utils/nameSuffix';

/**
 * Retro Bowl's own player sprites (New Star Games' art; the NFL edition's NFL and NFLPA marks) in
 * public/private-sprites/, committed and deployed by the owner's choice (2026-11-14). A build without that folder has
 * `__PRIVATE_SPRITES__` (vite.config.ts) false and fetches nothing: the site then looks exactly as it would without
 * this module. Two sources, in order:
 *   1. nfl/: the owner's own NFL Retro Bowl players from his save (scripts/pull_save.py, then
 *      scripts/private_nfl_sprites.py), 64 x 64 full-body sprites already drawn in real kits, several poses.
 *   2. the regular game's sheets (scripts/private_sprites.py): portraits, on-field poses and the helmet in placeholder
 *      key colours, recoloured into the club's kit (gameSpriteArt.ts), for players the save doesn't have.
 *
 * This file holds no art: only the key colours the game paints its placeholders in, and the rules mapping them.
 */

export type BodyPose = 'stand' | 'run' | 'celebrate' | 'jump' | 'dive' | 'stiffarm' | 'qb_throw';

export interface SpriteIndex {
  faces: { file: string; w: number; h: number; sheets: string[]; perSheet: number; keys: { shirt: string; trim: string; stripe?: string } };
  bodies: {
    file: string;
    cell: [number, number];
    poses: Record<string, { row: number; frames: number }>;
    keys: { helmet: string[]; jersey: string[]; pants: string[]; socks: string[]; skin: string[] };
  };
  helmet: { file: string; w: number; h: number; frames: number; keys: { shell: string; stripe: string; stripe2: string } };
}

/** The recoloured regular-game sheets (scripts/private_sprites.py): the fallback for players the save doesn't have. */
export interface RegularSprites {
  index: SpriteIndex;
  /** The recolouring code (gameSpriteArt.ts), loaded only once the sheets exist, so the public bundle never runs it */
  art: typeof SpriteArt;
  faces: HTMLImageElement;
  bodies: HTMLImageElement;
  helmet: HTMLImageElement;
  /** Skin locks from data/sprites.json (public data; the site's own looks), for the face pick */
  skins: Record<string, { skin?: unknown; build?: unknown; height?: unknown }>;
}

/** One player's sprites from the owner's NFL Retro Bowl save (scripts/private_nfl_sprites.py). */
export interface NflSpriteEntry {
  uid: string;
  /** Club name (as the site uses it) → poses drawn in that club's kit (1 = the standing pose) */
  kits: Record<string, number[]>;
  /** Poses in the neutral white kit (800) */
  neutral: number[];
  /** An assigned look (no true match in any save): a generic template or a real NFL player's sprite, picked by skin and
   * seeded by POS:Name (scripts/private_nfl_sprites.py); drawn like any neutral, painted into his club kit */
  assigned?: boolean;
  pool?: 'generic' | 'real';
  /**
   * NFL edition: club name → the files drawn in that club's famous era kit (`<uid>_<club>_era[_pN].png`, scripts/nfl/era.py):
   * the poses made, and `mid` when the middle season of his time with the club lies in the era (the era kit is then his
   * default kit there; a `season` in the era's span picks it too, one outside it the modern kit).
   */
  eras?: Record<string, { poses: number[]; mid?: boolean }>;
}
export interface NflSprites {
  size: [number, number];
  clubs: Record<string, number>;
  players: Record<string, NflSpriteEntry>;
  /** Real NFL legends (public/data/legends.json keys), for the arcade games only */
  legends?: Record<string, NflSpriteEntry>;
  /** The game's generated look templates (skin 0 dark, 1 mix, 2 light), worn by league players the save doesn't have */
  standins?: { uid: string; skin: number; neutral: number[] }[];
  /** file → [centre x of his legs, last row of his feet] in the 64 x 64 frame (scripts/private_nfl_sprites.py); a file
   * not listed stands at the body template's own [31.5, 58] (scripts/nfl/spritelib.py leaves those out) */
  anchors?: Record<string, [number, number]>;
  /** NFL edition: game face templates whose head outline fits (uids of `standins`), for the runtime silhouette */
  silhouetteHeads?: string[];
  /** NFL edition: club → its era kit and the seasons it was worn (src/config/eraKits.ts) */
  eraKits?: Record<string, { id: string; label: string; from: number; to: number }>;
  /** NFL edition: a file name the paths use → the file that holds the same image (identical sprites are stored once) */
  aliases?: Record<string, string>;
  /** The head coach and the coordinators (CoachSprite.tsx) */
  coaches?: NflCoaches;
  /**
   * Sharded index (scripts/perf/build_core.py, public/private-sprites/nfl/README.md): core.json carries the active
   * players, everyone else's entry and anchors are in shards/<i>.json, i = fnv1a("POS:Name") % count. Absent on a full
   * index.json (every player in `players`).
   */
  shards?: { count: number; file: string };
}

/**
 * One coach's sprites (scripts/private_nfl_sprites.py coach_sprites): a standing figure in a club polo per club the
 * save drew him for, a white neutral one, and the `mask` of his outfit pixels (64 rows of 16 hex digits, bit 63 - x =
 * column x), so a club he has no file for is painted exactly as the game paints a polo: neutral x club colour.
 */
export interface NflCoach {
  name: string;
  uid: string;
  /** Club name → file */
  kits: Record<string, string>;
  neutral: string;
  mask: string[];
  role?: 'HC' | 'OC' | 'DC';
  /** The save's club id (-1 = on the market) and its name */
  teamid?: number;
  club?: string | null;
}
export interface NflCoaches {
  head: NflCoach | null;
  staff: NflCoach[];
  /** Club name → the polo colour the game draws staff in (#rrggbb) */
  polo: Record<string, string>;
}

/**
 * Everything private this machine has. `nfl`: the owner's own NFL Retro Bowl players, already drawn in real kits
 * (primary). `regular`: the regular game's sheets, recoloured to a club's kit (fallback). Either may be null.
 */
export interface GameSprites {
  nfl: NflSprites | null;
  regular: RegularSprites | null;
  /** The site's locked looks (public data/sprites.json): skin, and height / build for the body (config/bodyTypes.ts) */
  looks?: Record<string, { skin?: unknown; build?: unknown; height?: unknown }> | null;
}

/**
 * The size system's shared frame (GameSprite.tsx, CoachSprite.tsx): a bust is the 64 x 64 sprite's head and shoulders,
 * 32 x 36 from row 6, centred on his centre line; a figure stands with the bottom of his feet on row 59 of its box.
 */
export const SPRITE_BUST = { y: 6, w: 32, h: 36 };
export const SPRITE_BASELINE = 59;

/** Build-time: true when public/private-sprites/ exists in the checkout that builds. */
const ENABLED = typeof __PRIVATE_SPRITES__ !== 'undefined' && __PRIVATE_SPRITES__;
export const PRIVATE_BASE = `${import.meta.env.BASE_URL}private-sprites/`;

// ---------- Loading (once, silent) ----------

let sprites: GameSprites | null = null;
let started = false;
/** Both sources have answered (or failed): until then a sprite box shows its loading mark instead of nothing. */
let settled = false;
const listeners = new Set<() => void>();
const publish = (part: Partial<GameSprites>) => {
  sprites = { nfl: null, regular: null, looks: null, ...sprites, ...part };
  listeners.forEach((l) => l());
};

const loadImage = (src: string) =>
  new Promise<HTMLImageElement>((resolve, reject) => {
    const img = new Image();
    img.decoding = 'async';
    img.onload = () => resolve(img);
    img.onerror = () => reject(new Error('sprite sheet'));
    img.src = src;
  });

/** JSON from the private folder, or null: a 404, or the dev server's SPA fallback (HTML) when the folder is gone. */
const privateJson = (path: string): Promise<unknown> =>
  dataResponse(`private-sprites/${path}`)
    .then((r) => (r.ok ? r.text() : null))
    .then((text) => {
      if (!text) return null;
      try {
        return JSON.parse(text) as unknown;
      } catch {
        return null;
      }
    })
    .catch(() => null);

const validIndex = (d: unknown): d is SpriteIndex => {
  const x = d as SpriteIndex | null;
  return !!x && typeof x === 'object' && !!x.faces?.file && !!x.bodies?.file && !!x.helmet?.file && Array.isArray(x.faces.sheets);
};
const validNfl = (d: unknown): d is NflSprites => {
  const x = d as NflSprites | null;
  return !!x && typeof x === 'object' && !!x.players && typeof x.players === 'object';
};

let looksJob: Promise<RegularSprites['skins']> | null = null;
/** The site's own locked looks (public data/sprites.json), fetched once. */
const siteLooks = () =>
  (looksJob ??= dataResponse('data/sprites.json')
    .then((r) => (r.ok ? r.json() : {}))
    .catch(() => ({}))
    .then((d: unknown) => (d && typeof d === 'object' ? (d as RegularSprites['skins']) : {})));

/** Fetches both indexes (and the regular sheets) once. Any failure = that source is absent; nothing is logged. */
export const loadGameSprites = (): void => {
  if (started || !ENABLED || typeof window === 'undefined') return;
  started = true;
  // the NFL index with the site's locked looks, together, so a locked body (Sherman Brandson) never draws twice
  const nflJob = Promise.all([privateJson('nfl/core.json').then((core) => core ?? privateJson('nfl/index.json')), siteLooks()]).then(([nfl, looks]) => {
    if (validNfl(nfl)) {
      const x = nfl as { save?: unknown; saveYears?: unknown; size?: unknown };
      setSpriteCacheStamp(JSON.stringify([x.save, x.saveYears, x.size, Object.keys((nfl as NflSprites).players).length]));
      setKitColors((nfl as { kitColors?: KitColors }).kitColors);
      setNumberTables(nfl as Parameters<typeof setNumberTables>[0]);
      setSockTemplate((nfl as { sockTemplate?: Record<string, string[]> }).sockTemplate);
      SPRITE_ALIASES = (nfl as NflSprites).aliases ?? {};
      donorsOf(nfl as NflSprites);
      publish({ nfl, looks });
    }
  });
  const regularJob = privateJson('index.json')
    .then(async (index) => {
      if (!validIndex(index)) return;
      const [faces, bodies, helmet] = await Promise.all([index.faces.file, index.bodies.file, index.helmet.file].map((f) => loadImage(PRIVATE_BASE + f)));
      const art = await import('./gameSpriteArt');
      const skins = await siteLooks();
      publish({ regular: { index, art, faces, bodies, helmet, skins } });
    })
    .catch(() => {
      /* no regular sheets: callers fall back silently */
    });
  Promise.allSettled([nflJob, regularJob]).then(() => {
    settled = true;
    listeners.forEach((l) => l());
  });
};

/** True while the sprite indexes are still loading on a machine that has them (never on the public site). */
export const SPRITES_ENABLED = ENABLED;
const loadingSnapshot = () => ENABLED && !settled;
/** The sprite indexes are still on their way: a sprite box draws its placeholder, not nothing (GameSprite, CoachSprite). */
export const useSpritesLoading = (): boolean => useSyncExternalStore(subscribe, loadingSnapshot, () => false);


// ---------- Sharded player index (retirees): fetched when a sprite asks for one ----------

const shardsLoaded = new Set<number>();
const shardJobs = new Map<number, Promise<void>>();
let shardPublish = 0;
const shardOfKey = (key: string, count: number) => fnvHash(key) % count;

/**
 * True when `key`'s sprite entry is available: it is in the index (an active player, or a full index.json) or its shard
 * has loaded. Otherwise starts that shard's fetch and returns false; the shard's arrival republishes the sprites, so
 * every GameSprite that asked draws again (until then it draws nothing, the same as before the index loads).
 */
const entryReady = (nfl: NflSprites, key: string): boolean => {
  if (nfl.players[key] || !nfl.shards) return true;
  const i = shardOfKey(key, nfl.shards.count);
  if (shardsLoaded.has(i)) return true;
  if (!shardJobs.has(i)) {
    shardJobs.set(
      i,
      privateJson(`nfl/${nfl.shards.file.replace('{i}', String(i))}`).then((raw) => {
        const sh = raw as { players?: Record<string, NflSpriteEntry>; anchors?: Record<string, [number, number]> } | null;
        if (sh?.players) Object.assign(nfl.players, sh.players);
        if (sh?.anchors) nfl.anchors = Object.assign(nfl.anchors ?? {}, sh.anchors);
        shardsLoaded.add(i);
        // one republish for the shards that land together (a list of 40 rows asks for up to 16)
        window.clearTimeout(shardPublish);
        shardPublish = window.setTimeout(() => sprites?.nfl && publish({ nfl: { ...sprites.nfl } }), 24);
      }),
    );
  }
  return false;
};

/** The key's shard is still loading (draw nothing yet rather than a stand-in he doesn't wear). */
export const spritePending = (nfl: NflSprites | null, key: string): boolean => !!nfl && !entryReady(nfl, key);

const subscribe = (l: () => void) => {
  listeners.add(l);
  loadGameSprites();
  return () => {
    listeners.delete(l);
  };
};
const snapshot = () => sprites;

/** The private sprites this machine has, or null (none here, or still loading). Callers choose a fallback. */
export const useGameSprites = (): GameSprites | null => useSyncExternalStore(subscribe, snapshot, () => null);

/**
 * Stature from the site's locked looks (data/sprites.json): a look marked build "huge" and height "tall" (Sherman
 * Brandson; owner: "he's supposed to be huge compared to everyone else but don't overdo it, just the sprite in the
 * banner") stands a step larger in the player banner (ProPlayerBanner.css turns it into whole pixels). 1 for everyone else.
 */
export const statureScale = (sprites: GameSprites | null, name: string): number => {
  const look = sprites?.looks?.[name] ?? sprites?.regular?.skins?.[name];
  return look && look.build === 'huge' && look.height === 'tall' ? 1.25 : 1;
};

// ---------- The owner's NFL save sprites (primary) ----------

/**
 * What a sprite is doing. Poses carry meaning and never cycle at random: idle (standing), celebrate (a correct answer,
 * a Hall of Fame induction, a title), run (loading states and transitions), stiffarm (a record falling).
 */
export type SpriteAction = 'idle' | 'celebrate' | 'run' | 'stiffarm';
/**
 * The save's five poses, as the files draw them (checked frame by frame, 2026-11-13): 1 standing, 2 ball at his side,
 * 3 arm raised high with the ball at his side, 4 ball tucked under the arm, 5 spinning the ball on one hand.
 */
export const NFL_POSE: Record<SpriteAction, number> = { idle: 1, celebrate: 3, run: 4, stiffarm: 4 };
/** The regular game's on-field poses for the same actions (animated unless reduced motion). */
export const REGULAR_POSE: Record<SpriteAction, BodyPose> = { idle: 'stand', celebrate: 'celebrate', run: 'run', stiffarm: 'stiffarm' };

export interface NflPick {
  /** The file to draw (a club kit as the save drew it, or the neutral white kit) */
  src: string;
  /** Club name of the kit drawn, or 'neutral' */
  kit: string;
  /** Club to paint the neutral kit into (gameKitPaint.ts); unset = draw src as is */
  paint?: string;
  pose: number;
  /** NFL edition: a runtime silhouette: the game face template file whose head outline replaces the donor's head (gameKitPaint.ts) */
  silhouette?: string;
  /** NFL edition: the club's era kit this file is drawn in (its label, e.g. "2001 Patriots"); the number is already his */
  era?: string;
  /** NFL edition: the club whose number colours to draw his real number in, set when the drawn number must be redone */
  numberClub?: string;
  /** The figure's centre line and feet row in the 64 x 64 frame (index anchors; the body template's 31.5, 58) */
  cx: number;
  foot: number;
}

/** File name (as a path builds it) → the file that holds the image (index.json `aliases`); set when the index loads. */
let SPRITE_ALIASES: Record<string, string> = {};
const nflFile = (uid: string, kit: number, pose: number, era = false) => {
  const name = `${uid}_${String(kit).padStart(3, '0')}${era ? '_era' : ''}${pose > 1 ? `_p${pose}` : ''}.png`;
  return `${PRIVATE_BASE}nfl/${SPRITE_ALIASES[name] ?? name}`;
};

/**
 * A player's NFL save sprite in his club's kit, in this order: the kit the save drew for that club (in the wanted
 * pose), the neutral white kit painted into the club's colours (gameKitPaint.ts), the club kit in another pose; null
 * when the save doesn't have him (the regular recolour is next, then nothing). `club` is his banner club, `current`
 * his current club (used only when he has no banner club). With no club at all he wears the neutral kit unpainted.
 * `legend`: a real NFL legend (index.legends), for the arcade games only.
 */
const withAnchor = (nfl: NflSprites, pick: Omit<NflPick, 'cx' | 'foot'> | null): NflPick | null => {
  if (!pick) return null;
  const a = nfl.anchors?.[pick.src.slice(pick.src.lastIndexOf('/') + 1)];
  return { ...pick, cx: a?.[0] ?? 31.5, foot: a?.[1] ?? 58 };
};

/**
 * NFL edition: free agents (team blank or FA) by `POS:Name` -> the club he is known for (banner / last club). A caller
 * that passes the player's current team (blank or FA) would otherwise draw him white; GameSprite and nflSpriteFor
 * read this so a free agent is always in his last club's kit.
 */
const FREE_AGENT_CLUBS = new Map<string, string>();
export const registerFreeAgents = (entries: Array<[string, string]>) => {
  FREE_AGENT_CLUBS.clear();
  entries.forEach(([k, c]) => c && FREE_AGENT_CLUBS.set(k, c));
};
export const freeAgentClub = (key: string): string | undefined => (IS_NFL ? FREE_AGENT_CLUBS.get(key) : undefined);

/** NFL edition: real jersey numbers by `POS:Name` (player-extras realNumbers), set when the league loads. */
let REAL_NUMBERS: Record<string, number> = {};
export const registerRealNumbers = (n: Record<string, number> | undefined) => {
  REAL_NUMBERS = n ?? {};
};
export const realNumberOf = (key: string): number | undefined => (IS_NFL ? REAL_NUMBERS[key] : undefined);

/**
 * The sprite's drawn number is his real one, redone where the file's isn't: every repainted or painted-neutral sprite
 * and the kit files index.json `numberFix` lists (a number he wore at another club). Sets `numberClub` on the pick.
 */
const withNumber = (pick: NflPick | null, key: string, legend: boolean): NflPick | null => {
  if (!pick || !IS_NFL || legend || realNumberOf(key) === undefined) return pick;
  const t = numberTables();
  if (!t) return pick;
  const file = pick.src.slice(pick.src.lastIndexOf('/') + 1);
  if (pick.paint) return { ...pick, numberClub: pick.paint.split('<')[0] };
  if (pick.kit !== 'neutral' && t.fix.has(file)) return { ...pick, numberClub: pick.kit };
  return pick;
};

export const nflSpriteFor = (
  nfl: NflSprites | null,
  key: string,
  club: string | undefined,
  current: string | undefined,
  action: SpriteAction = 'idle',
  legend = false,
  tone?: string,
  role = 1,
  season?: number,
): NflPick | null => {
  if (!nfl) return null;
  // a name from a game line, ESPN or an award list has no suffix: "RB:James Cook" is "RB:James Cook III" (his own sprite)
  if (IS_NFL && !legend) key = resolveSuffixKey(nfl.players, key);
  return withNumber(withAnchor(nfl, pickNfl(nfl, key, (!legend && freeAgentClub(key)) || club, current, action, legend, tone, role, season)), key, legend);
};

const STANDIN_SKINS: Record<string, number[]> = { pale: [2], light: [2], tan: [2, 1], medium: [1, 0], brown: [0], deep: [0] };

/**
 * A league player the save doesn't have wears one of the game's own look templates (index standins), a stable pick
 * seeded by his key within the templates matching his skin where the site knows it (sprites.json, the player editor),
 * so every player on the site is drawn in the same style; the kit is painted like any neutral sprite.
 */
const standinFor = (nfl: NflSprites, key: string, tone?: string): NflSpriteEntry | null => {
  const all = nfl.standins ?? [];
  const groups = tone ? STANDIN_SKINS[tone] : undefined;
  const pool = groups ? all.filter((x) => groups.includes(x.skin)) : all;
  const list = pool.length ? pool : all;
  if (!list.length) return null;
  const x = list[fnvHash(`${key}|standin`) % list.length];
  return { uid: x.uid, kits: {}, neutral: x.neutral };
};

// Donor bodies come from the core index only (the active players), fixed when the index loads: a shard landing later must
// not change which donor a silhouette gets
let DONORS: Record<string, NflSpriteEntry[]> | null = null;
const donorsOf = (nfl: NflSprites) => {
  if (!DONORS) {
    DONORS = {};
    for (const [k, e] of Object.entries(nfl.players)) {
      if ((e as { silhouette?: boolean }).silhouette || !e.neutral.length) continue;
      (DONORS[k.split(':')[0]] ??= []).push(e);
    }
  }
  return DONORS;
};
/**
 * NFL edition, the last resort: a player with no entry in the index (the owner banned random looks) is drawn as a
 * silhouette at runtime, the same look scripts/nfl/silhouettes.py bakes: a real player's neutral body of his position
 * (stable by his key) painted into his club's kit, his number in the game's font, the head replaced by the blacked-out
 * outline of a game face template with a 1px rim (gameKitPaint.ts silhouetteize). No club: the dark training kit.
 */
const silhouetteFallback = (nfl: NflSprites, key: string, target: string | undefined, action: SpriteAction, role: number): Omit<NflPick, 'cx' | 'foot'> | null => {
  const heads = nfl.silhouetteHeads;
  if (!heads?.length) return null;
  const by = donorsOf(nfl);
  const all = Object.values(by).flat();
  const list = by[key.split(':')[0]]?.length ? by[key.split(':')[0]] : all;
  if (!list.length) return null;
  const d = list[fnvHash(`${key}|donor`) % list.length];
  const want = action === 'idle' && role !== NFL_POSE.idle ? role : NFL_POSE[action];
  const pose = d.neutral.includes(want) ? want : d.neutral.includes(1) ? 1 : d.neutral[0];
  const team = target ? findNFLTeam(target)?.name : undefined;
  const head = heads[fnvHash(`${key}|head`) % heads.length];
  return { src: nflFile(d.uid, 800, pose), kit: team ?? 'neutral', paint: team ?? 'Training', pose, silhouette: nflFile(head, 800, pose) };
};

const pickNfl = (
  nfl: NflSprites,
  key: string,
  club: string | undefined,
  current: string | undefined,
  action: SpriteAction,
  legend: boolean,
  tone?: string,
  role = 1,
  season?: number,
): Omit<NflPick, 'cx' | 'foot'> | null => {
  if (!legend && !entryReady(nfl, key)) return null; // his shard is loading: neither a stand-in nor the silhouette
  if (IS_NFL && !legend && !nfl.players[key]) return silhouetteFallback(nfl, key, club || current, action, role);
  const e = legend ? nfl.legends?.[key] : nfl.players[key] ?? standinFor(nfl, key, tone);
  if (!e) return null;
  const want = NFL_POSE[action];
  const target = club || current;
  const id = target ? findNFLTeam(target)?.id : undefined;
  const kitName = target ? Object.keys(e.kits).find((k) => k.toLowerCase() === target.toLowerCase() || (!!id && findNFLTeam(k)?.id === id)) : undefined;
  const kitUid = kitName !== undefined ? nfl.clubs[kitName] : undefined;
  const poses = kitName ? e.kits[kitName] : [];
  const team = id ? findNFLTeam(target)!.name : undefined;
  // NFL edition: a club's famous era kit. With a season (the Deep Dive's career timeline, a season scene, a game log row) the
  // era kit is worn when that season lies in the era's span; with none, when the middle season of his time with the club
  // does (`mid`). Only a player who has era files for the club (index `eras`) is ever drawn in one.
  if (IS_NFL && !legend && e.eras) {
    const eraName = Object.keys(e.eras).find((k) => k.toLowerCase() === (target ?? '').toLowerCase() || (!!id && findNFLTeam(k)?.id === id));
    const info = eraName ? e.eras[eraName] : undefined;
    const span = eraName ? nfl.eraKits?.[eraName] : undefined;
    const kitUid2 = eraName ? nfl.clubs[eraName] : undefined;
    if (eraName && info && span && kitUid2 !== undefined && info.poses.length && (season !== undefined ? season >= span.from && season <= span.to : !!info.mid)) {
      const wanted = action === 'idle' && role !== want ? role : want;
      const pose = info.poses.includes(wanted) ? wanted : info.poses.includes(want) ? want : info.poses.includes(1) ? 1 : info.poses[0];
      return { src: nflFile(e.uid, kitUid2, pose, true), kit: eraName, pose, era: span.label };
    }
  }
  // playstyle (config/bodyTypes.ts rolePose): standing idle, he holds his role's pose, in his club's kit as the save
  // drew it or the neutral kit painted; explicit actions never come here
  if (action === 'idle' && role !== want) {
    if (kitName && kitUid !== undefined && poses.includes(role)) return { src: nflFile(e.uid, kitUid, role), kit: kitName, pose: role };
    if (team && e.neutral.includes(role)) return { src: nflFile(e.uid, 800, role), kit: team, paint: team, pose: role };
  }
  if (kitName && kitUid !== undefined && poses.includes(want)) return { src: nflFile(e.uid, kitUid, want), kit: kitName, pose: want };
  const neutralPose = e.neutral.includes(want) ? want : e.neutral[0];
  if (team && neutralPose !== undefined) return { src: nflFile(e.uid, 800, neutralPose), kit: team, paint: team, pose: neutralPose };
  if (kitName && kitUid !== undefined && poses.length) {
    const pose = poses.includes(1) ? 1 : poses[0];
    return { src: nflFile(e.uid, kitUid, pose), kit: kitName, pose };
  }
  // His own file exists only in other clubs' kits and he has no neutral to paint (a quarterback the save drew in the
  // Falcons' kit, now a Viking; a free agent): take one of his own kit files and repaint it into the club he is shown
  // in (gameKitPaint.ts repaintPixels, paint "Target<Source"), so his face is always his own.
  if (IS_NFL && team && !legend) {
    const from = Object.keys(e.kits).find((k) => e.kits[k].includes(want) && nfl.clubs[k] !== undefined) ?? Object.keys(e.kits).find((k) => e.kits[k].length && nfl.clubs[k] !== undefined);
    if (from) {
      const pose = e.kits[from].includes(want) ? want : e.kits[from][0];
      return { src: nflFile(e.uid, nfl.clubs[from], pose), kit: team, paint: `${team}<${from}`, pose };
    }
  }
  // NFL edition: no club to wear (a free agent never on a roster): the neutral dark training kit, never plain white
  if (neutralPose !== undefined) return IS_NFL && !legend && !(e as { training?: boolean }).training ? { src: nflFile(e.uid, 800, neutralPose), kit: 'neutral', paint: 'Training', pose: neutralPose } : { src: nflFile(e.uid, 800, neutralPose), kit: 'neutral', pose: neutralPose };
  return null;
};

// ---------- Coaches and coordinators ----------

export interface CoachPick {
  src: string;
  /** Club name of the polo drawn, or 'neutral' (white) */
  kit: string;
  /** Paint the neutral polo: a CSS colour and his outfit mask (gameKitPaint.ts) */
  polo?: { color: string; mask: string[] };
  cx: number;
  foot: number;
}

const plainName = (s: string) =>
  s
    .normalize('NFD')
    .replace(/[̀-ͯ]/g, '')
    .replace(/[^a-z]/gi, '')
    .toLowerCase();

/**
 * The head coach (`who` = 'head') or a coordinator (by name) in a club's polo: the file the save drew for that club,
 * else his white neutral painted in the club's polo colour (the save's own colour for the club; the site's primary
 * for a club no staff sprite shows), else the neutral as is. `club` unset = a coordinator's own club (the head coach's
 * club is the caller's to pass); null = the white neutral, club-neutral on purpose. Null when the save has no sprite.
 */
export const coachSpriteFor = (nfl: NflSprites | null, who: string, club?: string | null): CoachPick | null => {
  const c = nfl?.coaches;
  if (!nfl || !c) return null;
  const e = who === 'head' ? c.head : c.staff.find((s) => plainName(s.name) === plainName(who));
  if (!e) return null;
  const team = club === null ? null : findNFLTeam(club ?? e.club ?? undefined);
  const same = (k: string) => !!team && findNFLTeam(k)?.id === team.id;
  const at = (file: string) => {
    const a = nfl.anchors?.[file];
    return { src: `${PRIVATE_BASE}nfl/${file}`, cx: a?.[0] ?? 31.5, foot: a?.[1] ?? 58 };
  };
  const kitName = Object.keys(e.kits).find(same);
  if (kitName) return { ...at(e.kits[kitName]), kit: kitName };
  if (team && e.mask?.length === 64) {
    const color = c.polo[Object.keys(c.polo).find(same) ?? ''] ?? `hsl(${team.primaryColor})`;
    return { ...at(e.neutral), kit: team.name, polo: { color, mask: e.mask } };
  }
  return { ...at(e.neutral), kit: 'neutral' };
};

/** True when this machine has a sprite for the head coach ('head') or the named coordinator: callers lay out around him. */
export const useHasCoachSprite = (who: string): boolean => {
  const sprites = useGameSprites();
  return !!coachSpriteFor(sprites?.nfl ?? null, who);
};

// ---------- Which face ----------

/**
 * The game's own face fields, as a save record stores them: skin 0 dark (sheet spr_dark_00<face_y+1>, face_y 0-7),
 * 1 mix (spr_mix_001, face_y 0), 2 light (spr_light_00<face_y+1>, face_y 0-2); face_x 0-7 is the frame in that sheet.
 */
export interface GameFace {
  skin: 0 | 1 | 2;
  faceY: number;
  faceX: number;
}

export interface FaceSubject {
  name: string;
  position?: string;
  /** Skin tone from the player editor (types/player.ts) */
  spriteSkin?: string;
  /** Exact face from a save import (future); out-of-range values fall back to the seeded pick */
  gameFace?: Partial<GameFace> | null;
}

const FACE_Y_COUNT: Record<0 | 1 | 2, number> = { 0: 8, 1: 1, 2: 3 };

const validFace = (f: Partial<GameFace> | null | undefined): f is GameFace =>
  !!f &&
  (f.skin === 0 || f.skin === 1 || f.skin === 2) &&
  Number.isInteger(f.faceY) &&
  Number.isInteger(f.faceX) &&
  f.faceY! >= 0 &&
  f.faceY! < FACE_Y_COUNT[f.skin] &&
  f.faceX! >= 0 &&
  f.faceX! <= 7; // face_x 8 is a special case in the game's code: no exact face

/** Row of faces.png for a game face: dark 1-8 are rows 0-7, light 1-3 rows 8-10, mix 1 row 11. */
export const faceRow = (f: GameFace) => (f.skin === 0 ? f.faceY : f.skin === 2 ? 8 + f.faceY : 11);

// The site's six skin tones → the game's sheets (dark sheets 5-7 are the lighter browns).
type SkinTone = 'pale' | 'light' | 'tan' | 'medium' | 'brown' | 'deep'; // the site's tones (sprite/faces.ts)
const isSkinTone = (x: unknown): x is SkinTone => typeof x === 'string' && Object.prototype.hasOwnProperty.call(SHEETS_FOR_TONE, x);
const SHEETS_FOR_TONE: Record<SkinTone, Array<[0 | 1 | 2, number]>> = {
  pale: [[2, 0], [2, 1], [2, 2]],
  light: [[2, 0], [2, 1], [2, 2]],
  tan: [[2, 0], [2, 1], [2, 2], [1, 0]],
  medium: [[1, 0], [0, 4], [0, 5], [0, 6]],
  brown: [0, 1, 2, 3, 4, 5, 6, 7].map((y): [0, number] => [0, y]),
  deep: [0, 1, 2, 3, 7].map((y): [0, number] => [0, y]),
};
const ALL_SHEETS: Array<[0 | 1 | 2, number]> = [...SHEETS_FOR_TONE.brown, [1, 0], ...SHEETS_FOR_TONE.pale];

const fnvHash = (s: string) => {
  let h = 2166136261;
  for (let i = 0; i < s.length; i++) h = Math.imul(h ^ s.charCodeAt(i), 16777619);
  return h >>> 0;
};

/**
 * The face a player wears: his exact game face when a save import gives one, else a stable pick seeded by his key
 * (position:name; never Math.random, never the edition seed) within the sheets matching his skin where the site knows
 * it (sprites.json skin lock, then the player editor's toggle), else any of the 96. Both paths give a GameFace.
 */
export const faceFor = (player: FaceSubject, skinLocks?: Record<string, { skin?: unknown }> | null): GameFace & { exact: boolean } => {
  if (validFace(player.gameFace)) return { ...player.gameFace, exact: true };
  const locked = skinLocks?.[player.name]?.skin;
  const tone = isSkinTone(locked) ? locked : isSkinTone(player.spriteSkin) ? player.spriteSkin : null;
  const pool = tone ? SHEETS_FOR_TONE[tone] : ALL_SHEETS;
  const h = fnvHash(`${player.position ?? ''}:${player.name}|gameface`);
  const [skin, faceY] = pool[h % pool.length];
  return { skin, faceY, faceX: (h >>> 8) % 8, exact: false };
};

/** A sensible on-field pose for a position (the banner and roster figures). */
export const poseForPosition = (position: string | undefined): BodyPose => {
  switch (position) {
    case 'QB':
      return 'qb_throw';
    case 'RB':
      return 'stiffarm';
    case 'WR':
    case 'TE':
      return 'run';
    case 'DB':
    case 'LB':
    case 'DL':
      return 'run';
    default:
      return 'stand';
  }
};
