/**
 * League content (eras, Super Bowl history, storylines, rivalries…), loaded from
 * /data/league/content.json. scripts/build_league_content.py generates all of it by rules over the data in
 * data/y80; the only authored text is the owner's journal (quoted verbatim, `source: "owner"`) and the Hall of
 * Fame speeches. There is no in-browser override: new information enters through an upload bundle
 * (scripts/apply_upload.py), never by replacing this file.
 *
 * Format (all top-level arrays optional; unknown fields are ignored):
 * {
 *   "version": 1, "season": "Y80", "title": "...",
 *   "eras":       [{ id, name, startYear, endYear, superBowlRange?, yourTeams[], keyPlayers[], rival?, notes?, history? (markdown) }],
 *   "superBowls": [{ number, roman, year (number or "Y12"), winner, loser, score, yourResult: "won"|"lost"|"not in it"|"not captured", yourTeam }],
 *   "storylines": [{ id, headline, subheadline?, summary?, body (markdown), players[] (names), tier, category, era?, source? ("generated"|"owner") }],
 *   "rivalries":  [{ id, rival, team?, era?, summary, record?{ won, lost }, meetings?[{ roman, year, score, result, yourTeam, opponent }], ownerNotes?[JournalNote] }],
 *   "journal":    [{ id, text (owner's words), season?, kind?, players[], teams[] }],
 *   "lineages":   [{ id, label, chain[], note? }],
 *   "snubs":      [{ id, title?, summary (markdown), players[] }],
 *   "outsiders":  [{ player, position?, team?, summary }],
 *   "openQuestions": [string],
 *   "playerNotes":   [{ name, team?, position?, nickname?, era?, tag? }],
 *   "headlines":     [{ kind, text, players[] (names), teams[], weight }] ranked, heaviest first ("What changed")
 *   "headlinesInfo": { scope: "This update" | "Last update", upload?, since?, label? }
 *   "speeches":      { "<player name>": "Hall of Fame induction speech (plain text; blank line = new paragraph)" },
 *   "seasonStoryIndex": [{ season: "Y82", tagline, upload?, file: "stories/Y82.json", articleCount, didYouKnowCount,
 *                      lead?{ id, headline }, articles: [{ id, kind, headline }] }]
 *                      the Season Story (AI-authored, data/y80/stories.json): only an index here; each season's full
 *                      story is public/data/league/stories/<Y>.json, { season, tagline, upload?, articles: [{ id, kind,
 *                      headline, dek, body[], players[], teams[], stats[{ label, value, source }], related[] }],
 *                      didYouKnow: [{ id, text, players[], stats[] }] }, loaded on demand (loadSeasonStory / useSeasonStory)
 *   "hotTakesIndex": [{ season: "Y90", upload?, file: "takes.json", count, takes: [{ id, heat, headline }] }] newest first:
 *                      Hot Takes (AI-authored, data/y80/hot_takes.json, takes.set); the takes themselves are one file,
 *                      public/data/league/takes.json, { seasons: [{ season, upload?, intro?, takes: [{ id, heat (1-3),
 *                      headline, dek, body[], players[], teams[], stats[{ label, value, source }] }] }] } (newest first),
 *                      loaded on demand (loadHotTakes / useHotTakes)
 *   "tributeIndex":  [{ key: "RB:Ryland Maxwell", name, file: "tributes/rb-ryland-maxwell.json", upload?, nickname?, deck,
 *                      chapters: [{ id, kind, headline }] }]: Player Tributes (AI-authored, data/y80/tributes.json,
 *                      tribute.set); each tribute is its own file, loaded on demand (loadTribute / useTribute)
 *   "seasonRewindIndex": [{ season: "Y94", file: "rewind/Y94.json", club, champion?, record, count, kinds[] }] oldest
 *                      first: Season Rewind (rules only, scripts/season_rewind.py); each season's cards are
 *                      public/data/league/rewind/<Y>.json, loaded on demand (src/utils/seasonRewind.ts)
 *   "coach":         { name, age, stars, morale, gamesPlayed, simGames, record{}, bests{}, superBowlRecord[], seasons[{ year, team, abbr, w, l, t, finish }], currentStint?{ team, abbr, from } }
 * }
 * `coach` is optional (from data/y80/coach.json, the staff screen); bad fields are dropped one by one.
 * `speeches` is optional; when a player has one, the induction ceremony uses it instead of the
 * speech generated from their career data (see src/components/ceremony/speech.ts).
 * Eras/superBowls also accept the raw snake_case shape from data/y80
 * (years: "Y1–15", your_teams, key_players, your_result, your_team).
 */
import { useEffect, useState } from 'react';
import { seasonLabel } from '@/config/edition';
import { dataResponse } from '@/utils/dataStore';

