export type ContentSource = 'uploaded' | 'bundled' | 'none';

// ---------------------------------------------------------------------------
// Loose validation / normalization (fail soft: drop bad items, keep the rest)
// ---------------------------------------------------------------------------

type Raw = Record<string, unknown>;
const isObj = (v: unknown): v is Raw => typeof v === 'object' && v !== null && !Array.isArray(v);
const str = (v: unknown): string | undefined => (typeof v === 'string' && v.trim() ? v.trim() : undefined);
const strArr = (v: unknown): string[] => (Array.isArray(v) ? v.map(str).filter((s): s is string => !!s) : []);
const num = (v: unknown): number | undefined => {
  if (typeof v === 'number' && Number.isFinite(v)) return v;
  if (typeof v === 'string') {
    const n = parseInt(v.replace(/[^\d-]/g, ''), 10);
    return Number.isFinite(n) ? n : undefined;
  }
  return undefined;
};
const arr = (v: unknown): Raw[] => (Array.isArray(v) ? v.filter(isObj) : []);
const slug = (s: string) => s.toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/^-|-$/g, '');

const parseYearRange = (years?: string): [number, number] | null => {
  const m = years?.match(/Y?(\d+)\s*[–—-]\s*Y?(\d+)/);
  return m ? [parseInt(m[1], 10), parseInt(m[2], 10)] : null;
};

const normEra = (r: Raw): LeagueEra | null => {
  const name = str(r.name);
  if (!name) return null;
  let start = num(r.startYear);
  let end = num(r.endYear);
  if (start === undefined || end === undefined) {
    const range = parseYearRange(str(r.years));
    if (range) [start, end] = range;
  }
  if (start === undefined || end === undefined) return null;
  if (end < start) [start, end] = [end, start];
  return {
    id: str(r.id) ?? slug(name),
    name,
    startYear: start,
    endYear: end,
    superBowlRange: str(r.superBowlRange) ?? str(r.super_bowls),
    yourTeams: strArr(r.yourTeams ?? r.your_teams),
    keyPlayers: strArr(r.keyPlayers ?? r.key_players),
    rival: str(r.rival),
    notes: str(r.notes),
    history: str(r.history),
  };
};

const RESULTS: SuperBowlResult[] = ['won', 'lost', 'not in it', 'not captured'];
const normSuperBowl = (r: Raw): SuperBowlEntry | null => {
  const year = num(r.year);
  if (year === undefined) return null;
  const rawResult = (str(r.yourResult) ?? str(r.your_result) ?? '').toLowerCase();
  const yourResult: SuperBowlResult =
    (RESULTS as string[]).includes(rawResult) ? (rawResult as SuperBowlResult)
      : rawResult === 'win' ? 'won' : rawResult === 'loss' ? 'lost' : rawResult ? 'not in it' : 'not captured';
  return {
    number: num(r.number) ?? year + 59,
    roman: str(r.roman) ?? '',
    year,
    winner: str(r.winner) ?? null,
    loser: str(r.loser) ?? null,
    score: str(r.score) ?? null,
    yourResult,
    yourTeam: str(r.yourTeam) ?? str(r.your_team) ?? null,
  };
};

const normStory = (r: Raw, i: number): Storyline | null => {
  const headline = str(r.headline) ?? str(r.title);
  const body = str(r.body) ?? str(r.content) ?? str(r.summary);
  if (!headline || !body) return null;
  const tier = str(r.tier) as StoryTier | undefined;
  return {
    id: str(r.id) ?? `story-${i}-${slug(headline)}`,
    headline,
    subheadline: str(r.subheadline),
    summary: str(r.summary),
    body,
    players: strArr(r.players),
    tier: tier && (STORY_TIERS as readonly string[]).includes(tier) ? tier : 'analysis',
    category: str(r.category) ?? 'League History',
    era: str(r.era),
    source: r.source === 'owner' ? 'owner' : 'generated',
  };
};

const normNote = (r: Raw, i: number): JournalNote | null => {
  const text = str(r.text);
  return text
    ? { id: str(r.id) ?? `note-${i}`, text, season: str(r.season), kind: str(r.kind), players: strArr(r.players), teams: strArr(r.teams) }
    : null;
};

const normRivalry = (r: Raw, i: number): Rivalry | null => {
  const rival = str(r.rival) ?? str(r.name);
  const summary = str(r.summary) ?? str(r.body);
  if (!rival || !summary) return null;
  return {
    id: str(r.id) ?? `rivalry-${i}`,
    rival,
    team: str(r.team),
    era: str(r.era),
    summary,
    record: isObj(r.record) && count(r.record.won) !== undefined && count(r.record.lost) !== undefined
      ? { won: count(r.record.won)!, lost: count(r.record.lost)! }
      : undefined,
    ownerNotes: arr(r.ownerNotes).map(normNote).filter((n): n is JournalNote => !!n),
    meetings: arr(r.meetings).map((m) => ({
      roman: str(m.roman),
      year: num(m.year),
      score: str(m.score),
      result: str(m.result),
      yourTeam: str(m.yourTeam),
      opponent: str(m.opponent),
    })),
    games: isObj(r.games) && Array.isArray(r.games.meetings) ? (r.games as unknown as Rivalry['games']) : undefined,
    source: str(r.source),
    file: str(r.file),
    lasting: typeof r.lasting === 'boolean' ? r.lasting : undefined,
  };
};

const normLineage = (r: Raw, i: number): Lineage | null => {
  const chain = strArr(r.chain);
  if (!chain.length) return null;
  return { id: str(r.id) ?? `lineage-${i}`, label: str(r.label) ?? 'Lineage', chain, note: str(r.note) };
};

const normSnub = (r: Raw, i: number): Snub | null => {
  const summary = str(r.summary) ?? str(r.body);
  if (!summary) return null;
  return { id: str(r.id) ?? `snub-${i}`, title: str(r.title), summary, players: strArr(r.players) };
};

const speechMap = (v: unknown): Record<string, string> | undefined => {
  if (!isObj(v)) return undefined;
  const out: Record<string, string> = {};
  Object.entries(v).forEach(([name, text]) => {
    const t = str(text);
    if (name.trim() && t) out[name.trim()] = t;
  });
  return Object.keys(out).length ? out : undefined;
};

/** Strict number: only real finite numbers or plain numeric strings (no "Y12" coercion). */
const strictNum = (v: unknown): number | undefined => {
  if (typeof v === 'number' && Number.isFinite(v)) return v;
  if (typeof v === 'string' && /^\s*-?\d+(\.\d+)?\s*$/.test(v)) return Number(v);
  return undefined;
};
const RECORD_RE = /^\d+\s*-\s*\d+(\s*-\s*\d+)?$/;
const recordStr = (v: unknown) => {
  const s = str(v);
  return s && RECORD_RE.test(s) ? s.replace(/\s+/g, '') : undefined;
};
const pct = (v: unknown) => {
  const n = strictNum(v);
  return n !== undefined && n >= 0 && n <= 1 ? n : undefined;
};
const count = (v: unknown) => {
  const n = strictNum(v);
  return n !== undefined && n >= 0 && Number.isInteger(n) ? n : undefined;
};
/** Drop undefined keys so optional objects stay clean. */
const prune = <T extends object>(o: T): T | undefined => {
  const entries = Object.entries(o).filter(([, v]) => v !== undefined);
  return entries.length ? (Object.fromEntries(entries) as T) : undefined;
};

const normCoachSeason = (r: Raw): CoachSeason | null => {
  const year = num(r.year);
  const team = str(r.team) ?? str(r.abbr);
  const w = count(r.w);
  const l = count(r.l);
  const finish = str(r.finish);
  if (year === undefined || year < 1 || !team || w === undefined || l === undefined || !finish) return null;
  return { year, team, abbr: str(r.abbr), w, l, t: count(r.t) ?? 0, finish };
};

const normCoach = (v: unknown): CoachInfo | undefined => {
  if (!isObj(v)) return undefined;
  const rec = isObj(v.record) ? v.record : {};
  const bests = isObj(v.bests) ? v.bests : {};
  const reached = str(rec.playoffsReached);
  const stars = strictNum(v.stars);
  const byYear = new Map<number, CoachSeason>();
  compact(arr(v.seasons).map(normCoachSeason)).forEach((s) => !byYear.has(s.year) && byYear.set(s.year, s));
  const coach: CoachInfo = {
    name: str(v.name),
    age: count(v.age),
    stars: stars !== undefined && stars >= 0 && stars <= 5 ? stars : undefined,
    morale: str(v.morale),
    gamesPlayed: count(v.gamesPlayed),
    simGames: count(v.simGames),
    record: prune<CoachRecord>({
      fullSeasons: count(rec.fullSeasons),
      regular: recordStr(rec.regular),
      regularWinPct: pct(rec.regularWinPct),
      playoff: recordStr(rec.playoff),
      playoffWinPct: pct(rec.playoffWinPct),
      playoffsReached: reached && /^\d+\s*\/\s*\d+$/.test(reached) ? reached.replace(/\s+/g, '') : undefined,
      seasonsNoSimGames: count(rec.seasonsNoSimGames),
      simGameRecord: recordStr(rec.simGameRecord),
    }),
    bests: prune<CoachBests>({
      mostPoints: str(bests.mostPoints),
      biggestWin: str(bests.biggestWin),
      biggestLoss: str(bests.biggestLoss),
      mostTDs: str(bests.mostTDs),
    }),
    superBowlRecord: compact(
      arr(v.superBowlRecord).map((r) => {
        const c = str(r.coach);
        const titles = count(r.titles);
        return c && titles !== undefined ? { coach: c, titles } : null;
      }),
    ),
    seasons: [...byYear.values()].sort((a, b) => a.year - b.year),
  };
  const cleaned = prune(coach);
  if (!cleaned || (!coach.name && !coach.seasons.length && !coach.record && !coach.superBowlRecord.length)) return undefined;
  const cs = isObj(v.currentStint) ? v.currentStint : {};
  const csTeam = str(cs.team);
  const csFrom = count(cs.from);
  const currentStint = csTeam && csFrom ? { team: csTeam, abbr: str(cs.abbr), from: csFrom } : undefined;
  return { ...cleaned, superBowlRecord: coach.superBowlRecord, seasons: coach.seasons, ...(currentStint ? { currentStint } : {}) };
};

const compact = <T,>(items: (T | null)[]): T[] => items.filter((x): x is T => x !== null);

/** Normalize anything JSON-ish into LeagueContent. Throws only if it's unusable. */
export const normalizeLeagueContent = (input: unknown): LeagueContent => {
  if (!isObj(input)) throw new Error('Content must be a JSON object.');
  const content: LeagueContent = {
    version: num(input.version) ?? 1,
    season: str(input.season),
    title: str(input.title),
    eras: compact(arr(input.eras).map(normEra)).sort((a, b) => a.startYear - b.startYear),
    superBowls: compact(arr(input.superBowls ?? input.super_bowls).map(normSuperBowl)).sort((a, b) => a.year - b.year),
    storylines: compact(arr(input.storylines ?? input.stories).map(normStory)),
    rivalries: compact(arr(input.rivalries).map(normRivalry)),
    lineages: compact(arr(input.lineages).map(normLineage)),
    snubs: compact(arr(input.snubs).map(normSnub)),
    outsiders: compact(
      arr(input.outsiders).map((r) => {
        const player = str(r.player) ?? str(r.name);
        const summary = str(r.summary) ?? '';
        return player ? { player, position: str(r.position), team: str(r.team), summary } : null;
      }),
    ),
    openQuestions: strArr(input.openQuestions),
    playerNotes: compact(
      arr(input.playerNotes).map((r) => {
        const name = str(r.name);
        return name
          ? { name, team: str(r.team), position: str(r.position), nickname: str(r.nickname), era: str(r.era), tag: str(r.tag) }
          : null;
      }),
    ),
  };
  const journal = arr(input.journal).map(normNote).filter((n): n is JournalNote => !!n);
  if (journal.length) content.journal = journal;
  const speeches = speechMap(input.speeches);
  if (speeches) content.speeches = speeches;
  const coach = normCoach(input.coach);
  if (coach) content.coach = coach;
  if (isObj(input.edition) && num(input.edition.seed) !== undefined) {
    const e = input.edition;
    content.edition = { number: num(e.number) ?? 0, season: str(e.season), upload: str(e.upload), seed: num(e.seed)!, label: str(e.label) };
  }
  const headlines = compact(
    arr(input.headlines).map((r) => {
      const text = str(r.text);
      const kind = str(r.kind) as HeadlineKind | undefined;
      return text && kind && (HEADLINE_KINDS as readonly string[]).includes(kind)
        ? { kind, text, players: strArr(r.players), teams: strArr(r.teams), weight: num(r.weight) ?? 0 }
        : null;
    }),
  );
  if (headlines.length) content.headlines = headlines;
  if (isObj(input.headlinesInfo)) {
    const h = input.headlinesInfo;
    content.headlinesInfo = {
      scope: h.scope === 'Last update' ? 'Last update' : 'This update',
      upload: str(h.upload),
      since: str(h.since),
      label: str(h.label),
    };
  }
  const storyIndex = compact(
    arr(input.seasonStoryIndex).map((r): SeasonStoryIndexEntry | null => {
      const season = str(r.season);
      if (!season || !/^Y\d+$/.test(season)) return null;
      const articles = compact(
        arr(r.articles).map((a) => {
          const id = str(a.id);
          const kind = str(a.kind) as StoryKind | undefined;
          const headline = str(a.headline);
          return id && headline && kind && (STORY_KINDS as readonly string[]).includes(kind) ? { id, kind, headline } : null;
        }),
      );
      const leadId = isObj(r.lead) ? str(r.lead.id) : undefined;
      const leadHeadline = isObj(r.lead) ? str(r.lead.headline) : undefined;
      const file = str(r.file);
      return {
        season,
        tagline: str(r.tagline) ?? '',
        upload: str(r.upload),
        // only a season file under stories/ (never an arbitrary path)
        file: file && /^stories\/Y\d+\.json$/.test(file) ? file : `stories/${season}.json`,
        articleCount: num(r.articleCount) ?? articles.length,
        didYouKnowCount: num(r.didYouKnowCount) ?? 0,
        lead: leadId && leadHeadline ? { id: leadId, headline: leadHeadline } : undefined,
        articles,
      };
    }),
  );
  if (storyIndex.length) content.seasonStoryIndex = storyIndex;
  const takesIndex = compact(
    arr(input.hotTakesIndex).map((r): HotTakesIndexEntry | null => {
      const season = str(r.season);
      if (!season || !/^Y\d+$/.test(season)) return null;
      const takes = compact(
        arr(r.takes).map((t) => {
          const id = str(t.id);
          const headline = str(t.headline);
          const heat = takeHeat(t.heat);
          return id && headline && heat ? { id, heat, headline } : null;
        }),
      );
      return { season, upload: str(r.upload), file: 'takes.json', count: num(r.count) ?? takes.length, takes };
    }),
  );
  if (takesIndex.length) content.hotTakesIndex = takesIndex;
  const tributeIndex = compact(
    arr(input.tributeIndex).map((r): TributeIndexEntry | null => {
      const key = str(r.key);
      const name = str(r.name);
      const file = str(r.file);
      // only a tribute file under tributes/ (never an arbitrary path)
      if (!key || !name || !file || !/^tributes\/[a-z0-9-]+\.json$/.test(file)) return null;
      const chapters = compact(
        arr(r.chapters).map((c) => {
          const id = str(c.id);
          const headline = str(c.headline);
          const kind = str(c.kind) as TributeKind | undefined;
          return id && headline && kind && (TRIBUTE_KINDS as readonly string[]).includes(kind) ? { id, kind, headline } : null;
        }),
      );
      return { key, name, file, upload: str(r.upload), nickname: str(r.nickname), deck: str(r.deck) ?? '', chapters };
    }),
  );
  if (tributeIndex.length) content.tributeIndex = tributeIndex;
  const rewindIndex = compact(
    arr(input.seasonRewindIndex).map((r): SeasonRewindIndexEntry | null => {
      const season = str(r.season);
      const file = str(r.file);
      // only a season file under rewind/ (never an arbitrary path)
      if (!season || !/^Y\d+$/.test(season) || !file || file !== `rewind/${season}.json`) return null;
      return { season, file, club: str(r.club), champion: str(r.champion), record: str(r.record), count: num(r.count) ?? 0, kinds: strArr(r.kinds) };
    }),
  );
  if (rewindIndex.length) content.seasonRewindIndex = rewindIndex;
  // Rivalry files pass through raw; utils/rivalryFiles.ts rivalryFilesOf checks them field by field
  if (Array.isArray(input.rivalryFiles)) content.rivalryFiles = input.rivalryFiles;
  if (Array.isArray(input.hofClasses)) {
    const classes = input.hofClasses
      .map((c) => (isObj(c) && str(c.label) && Array.isArray(c.keys) ? { label: str(c.label)!, keys: c.keys.filter((k): k is string => typeof k === 'string') } : null))
      .filter((c): c is { label: string; keys: string[] } => !!c && c.keys.length > 0);
    if (classes.length) content.hofClasses = classes;
  }
  const hasAnything =
    content.eras.length || content.superBowls.length || content.storylines.length || content.rivalries.length ||
    content.lineages.length || content.snubs.length;
  if (!hasAnything) {
    throw new Error('No eras, superBowls, storylines, rivalries, lineages or snubs found.');
  }
  return content;
};

/** Parse content.json text; throws a user-readable Error. */
export const parseLeagueContent = (text: string): LeagueContent => {
  let json: unknown;
  try {
    json = JSON.parse(text);
  } catch {
    throw new Error('That file is not valid JSON.');
  }
  return normalizeLeagueContent(json);
};

// ---------------------------------------------------------------------------
// Loading
// ---------------------------------------------------------------------------

/** Older builds let a browser override content.json with an uploaded file; drop any leftover copy. */
const dropLegacyUpload = () => {
  try {
    localStorage.removeItem(CONTENT_STORAGE_KEY);
  } catch {
    /* storage unavailable */
  }
};

let bundledPromise: Promise<LeagueContent | null> | null = null;
const fetchBundled = (): Promise<LeagueContent | null> => {
  if (!bundledPromise) {
    // no-cache: always revalidate so a rebuilt content.json (e.g. new speeches) shows on the next load
    bundledPromise = dataResponse('data/league/content.json')
      .then((res) => (res.ok ? res.json() : null))
      .then((json) => (json ? normalizeLeagueContent(json) : null))
      .catch(() => null);
  }
  return bundledPromise;
};

/** The generated content.json. Never throws. */
export const loadLeagueContent = async (): Promise<{ content: LeagueContent | null; source: ContentSource }> => {
  dropLegacyUpload();
  const bundled = await fetchBundled();
  return bundled ? { content: bundled, source: 'bundled' } : { content: null, source: 'none' };
};

// ---------------------------------------------------------------------------
// React hook
// ---------------------------------------------------------------------------

export const useLeagueContent = () => {
  const [state, setState] = useState<{ content: LeagueContent | null; source: ContentSource; loading: boolean }>(
    { content: null, source: 'none', loading: true },
  );

  useEffect(() => {
    let cancelled = false;
    loadLeagueContent().then((res) => {
      if (!cancelled) setState({ ...res, loading: false });
    });
    return () => {
      cancelled = true;
    };
  }, []);

  return state;
};

// ---------------------------------------------------------------------------
// Season stories (one file per season, loaded on demand)
// ---------------------------------------------------------------------------

const storyStats = (v: unknown): StoryStat[] =>
  compact(
    arr(v).map((x) => {
      const label = str(x.label);
      const value = typeof x.value === 'number' ? String(x.value) : str(x.value);
      return label && value ? { label, value, source: str(x.source) ?? '' } : null;
    }),
  );

/** One season's story file (public/data/league/stories/<Y>.json); null when it has no season or no articles. */
export const normalizeSeasonStory = (r: unknown): SeasonStory | null => {
  if (!isObj(r)) return null;
  const season = str(r.season);
  const articles = compact(
    arr(r.articles).map((a): StoryArticle | null => {
      const id = str(a.id);
      const kind = str(a.kind) as StoryKind | undefined;
      const headline = str(a.headline);
      if (!id || !headline || !kind || !(STORY_KINDS as readonly string[]).includes(kind)) return null;
      return { id, kind, headline, dek: str(a.dek) ?? '', body: strArr(a.body), players: strArr(a.players), teams: strArr(a.teams), stats: storyStats(a.stats), related: strArr(a.related), art: artHint(a.art) };
    }),
  );
  const didYouKnow = compact(
    arr(r.didYouKnow).map((x) => {
      const id = str(x.id);
      const text = str(x.text);
      return id && text ? { id, text, players: strArr(x.players), teams: strArr(x.teams), stats: storyStats(x.stats) } : null;
    }),
  );
  return season && articles.length ? { season, tagline: str(r.tagline) ?? '', upload: str(r.upload), articles, didYouKnow } : null;
};

/** Requests per story file, so each season is fetched once per page load */
const storyRequests = new Map<string, Promise<SeasonStory | null>>();
/** Seasons already in, for a first render with no loading frame */
const storiesLoaded = new Map<string, SeasonStory | null>();

/** Fetches one season's full story (memoized per file; no-cache revalidates a rebuilt file). Never throws; null if missing. */
export const loadSeasonStory = (entry: Pick<SeasonStoryIndexEntry, 'season' | 'file'>): Promise<SeasonStory | null> => {
  const key = entry.file;
  let req = storyRequests.get(key);
  if (!req) {
    req = dataResponse(`data/league/${entry.file}`)
      .then((res) => (res.ok ? res.json() : null))
      .then((json) => {
        const s = normalizeSeasonStory(json);
        return s && s.season === entry.season ? s : null;
      })
      .catch(() => null)
      .then((s) => {
        storiesLoaded.set(key, s);
        // a failed load may be retried on the next request
        if (!s) storyRequests.delete(key);
        return s;
      });
    storyRequests.set(key, req);
  }
  return req;
};

/** The index entry that holds an article id (a deep link's season) */
export const storyEntryOf = (index: SeasonStoryIndexEntry[] | undefined, articleId: string) =>
  index?.find((e) => e.articles.some((a) => a.id === articleId));

/** One season's full story: `loading` until its file is in; `story` null when it failed or there is none. */
export const useSeasonStory = (entry: SeasonStoryIndexEntry | null | undefined) => {
  const key = entry?.file;
  const cached = key ? storiesLoaded.get(key) : undefined;
  const [state, setState] = useState<{ key?: string; story: SeasonStory | null }>({ key: cached !== undefined ? key : undefined, story: cached ?? null });
  useEffect(() => {
    if (!entry) return;
    let alive = true;
    loadSeasonStory(entry).then((story) => alive && setState({ key: entry.file, story }));
    return () => {
      alive = false;
    };
  }, [entry]);
  // a state left from another season (just switched) never shows: it reads as loading until this season's file is in
  const ready = !!key && (state.key === key || storiesLoaded.has(key));
  const story = ready ? (state.key === key ? state.story : storiesLoaded.get(key!) ?? null) : null;
  return { story, loading: !!entry && !ready };
};

// ---------------------------------------------------------------------------
// Hot Takes (one file, every season, newest first; loaded on demand)
// ---------------------------------------------------------------------------

const takeHeat = (v: unknown): TakeHeat | undefined => (v === 1 || v === 2 || v === 3 ? v : undefined);

/** public/data/league/takes.json; seasons without a usable take are dropped */
export const normalizeHotTakes = (r: unknown): HotTakesSeason[] =>
  compact(
    arr(isObj(r) ? r.seasons : undefined).map((s): HotTakesSeason | null => {
      const season = str(s.season);
      const takes = compact(
        arr(s.takes).map((t): HotTake | null => {
          const id = str(t.id);
          const headline = str(t.headline);
          const heat = takeHeat(t.heat);
          if (!id || !headline || !heat) return null;
          return { id, heat, headline, dek: str(t.dek) ?? '', body: strArr(t.body), players: strArr(t.players), teams: strArr(t.teams), stats: storyStats(t.stats), art: artHint(t.art) };
        }),
      );
      return season && /^Y\d+$/.test(season) && takes.length ? { season, upload: str(s.upload), intro: str(s.intro), takes } : null;
    }),
  ).sort((a, b) => Number(b.season.slice(1)) - Number(a.season.slice(1)));

let takesRequest: Promise<HotTakesSeason[] | null> | null = null;
let takesLoaded: HotTakesSeason[] | null | undefined;

/** Fetches every season's Hot Takes once per page load (no-cache revalidates a rebuilt file). Never throws; null on failure. */
export const loadHotTakes = (): Promise<HotTakesSeason[] | null> => {
  if (!takesRequest) {
    takesRequest = dataResponse('data/league/takes.json')
      .then((res) => (res.ok ? res.json() : null))
      .then((json) => (json ? normalizeHotTakes(json) : null))
      .catch(() => null)
      .then((t) => {
        takesLoaded = t;
        // a failed load may be retried on the next request
        if (!t) takesRequest = null;
        return t;
      });
  }
  return takesRequest;
};

/** Every season's Hot Takes (newest first): `loading` until the file is in; `seasons` empty when it failed or there are none. */
export const useHotTakes = (enabled = true) => {
  const [seasons, setSeasons] = useState<HotTakesSeason[] | null | undefined>(takesLoaded);
  useEffect(() => {
    if (!enabled || takesLoaded !== undefined) return;
    let alive = true;
    loadHotTakes().then((t) => alive && setSeasons(t));
    return () => {
      alive = false;
    };
  }, [enabled]);
  const value = seasons ?? takesLoaded;
  return { seasons: value ?? [], loading: enabled && value === undefined, failed: value === null };
};

// ---------------------------------------------------------------------------
// Player Tributes (one file per tribute; loaded on demand)
// ---------------------------------------------------------------------------

const numOr = (v: unknown, d = 0) => num(v) ?? d;

const tradeOf = (r: unknown): TributeTrade | undefined => {
  if (!isObj(r)) return undefined;
  const sides = arr(r.sides).map((sd) => ({
    to: str(sd.to) ?? '',
    value: numOr(sd.value),
    players: compact(
      arr(sd.players).map((x): TributeTradePlayer | null => {
        const key = str(x.key);
        if (!key) return null;
        const after = isObj(x.after) ? { games: numOr(x.after.games), rings: numOr(x.after.rings) } : undefined;
        return { key, name: str(x.name) ?? key, pos: str(x.pos) ?? '', ovr: num(x.ovr), grade: str(x.grade), value: num(x.value), games: num(x.games), after, played: typeof x.played === 'boolean' ? x.played : undefined };
      }),
    ),
  }));
  const after = str(r.after);
  const snapshot = str(r.snapshot);
  return after && snapshot && sides.length >= 2 ? { after, snapshot, label: str(r.label), later: str(r.later), laterLabel: str(r.laterLabel), sides } : undefined;
};

const marketOf = (r: unknown): TributeMarket | undefined => {
  if (!isObj(r)) return undefined;
  const series = compact(
    arr(r.series).map((x) => {
      const season = str(x.season);
      if (!season || !isObj(x.values)) return null;
      const values: Record<string, number> = {};
      Object.entries(x.values).forEach(([k, v]) => typeof v === 'number' && Number.isFinite(v) && (values[k] = v));
      return { season, snapshot: str(x.snapshot) ?? '', ovr: num(x.ovr), grade: str(x.grade), values };
    }),
  );
  return series.length ? { players: strArr(r.players), series } : undefined;
};

const rivalOf = (r: unknown): TributeRival | undefined => {
  if (!isObj(r)) return undefined;
  const player = str(r.player);
  const name = str(r.name);
  if (!player || !name) return undefined;
  const rows = compact(arr(r.rows).map((x) => (str(x.label) ? { label: str(x.label)!, a: numOr(x.a), b: numOr(x.b), decimals: numOr(x.decimals) } : null)));
  return { player, name, pos: str(r.pos) ?? '', nickname: str(r.nickname), rows };
};

/** One tribute file (public/data/league/tributes/<pos-name>.json); null without a key or chapters */
export const normalizeTribute = (r: unknown): Tribute | null => {
  if (!isObj(r)) return null;
  const key = str(r.key);
  const name = str(r.name);
  const chapters = compact(
    arr(r.chapters).map((c): TributeChapter | null => {
      const id = str(c.id);
      const kind = str(c.kind) as TributeKind | undefined;
      const headline = str(c.headline);
      if (!id || !headline || !kind || !(TRIBUTE_KINDS as readonly string[]).includes(kind)) return null;
      return {
        id,
        kind,
        club: str(c.club),
        headline,
        dek: str(c.dek),
        body: strArr(c.body),
        players: strArr(c.players),
        teams: strArr(c.teams),
        stats: storyStats(c.stats),
        art: artHint(c.art),
        trade: kind === 'trade' ? tradeOf(c.data) : undefined,
        market: kind === 'market' ? marketOf(c.data) : undefined,
        rival: kind === 'rival' ? rivalOf(c.data) : undefined,
      };
    }),
  );
  if (!key || !name || !chapters.length) return null;
  const h = isObj(r.hero) ? r.hero : {};
  const journey = compact(
    arr(r.journey).map((j) => {
      const team = str(j.team);
      return team ? { team, from: numOr(j.from), to: numOr(j.to), rings: Array.isArray(j.rings) ? j.rings.filter((y): y is number => typeof y === 'number') : [] } : null;
    }),
  );
  return {
    key,
    name,
    pos: str(r.pos) ?? key.split(':')[0],
    upload: str(r.upload),
    nickname: str(r.nickname),
    deck: str(r.deck) ?? '',
    hero: { games: numOr(h.games), clubs: numOr(h.clubs), active: h.active === true, careerLegacy: numOr(h.careerLegacy), rings: numOr(h.rings), hallOfFame: str(h.hallOfFame) },
    journey,
    chapters,
  };
};

const tributeRequests = new Map<string, Promise<Tribute | null>>();
const tributesLoaded = new Map<string, Tribute | null>();

/** Fetches one tribute (memoized per file; no-cache revalidates a rebuilt file). Never throws; null if missing. */
export const loadTribute = (entry: Pick<TributeIndexEntry, 'key' | 'file'>): Promise<Tribute | null> => {
  let req = tributeRequests.get(entry.file);
  if (!req) {
    req = dataResponse(`data/league/${entry.file}`)
      .then((res) => (res.ok ? res.json() : null))
      .then((json) => {
        const t = normalizeTribute(json);
        return t && t.key === entry.key ? t : null;
      })
      .catch(() => null)
      .then((t) => {
        tributesLoaded.set(entry.file, t);
        // a failed load may be retried on the next request
        if (!t) tributeRequests.delete(entry.file);
        return t;
      });
    tributeRequests.set(entry.file, req);
  }
  return req;
};

/** The index entry of a player's tribute ("POS:Name"), if he has one */
export const tributeEntryOf = (content: LeagueContent | null | undefined, key: string | null | undefined) =>
  key ? content?.tributeIndex?.find((e) => e.key === key) : undefined;

/** One tribute: `loading` until its file is in; `tribute` null when it failed or there is none. */
export const useTribute = (entry: TributeIndexEntry | null | undefined) => {
  const file = entry?.file;
  const [state, setState] = useState<{ file?: string; tribute: Tribute | null }>(() => ({ file: file && tributesLoaded.has(file) ? file : undefined, tribute: file ? tributesLoaded.get(file) ?? null : null }));
  useEffect(() => {
    if (!entry) return;
    let alive = true;
    loadTribute(entry).then((tribute) => alive && setState({ file: entry.file, tribute }));
    return () => {
      alive = false;
    };
  }, [entry]);
  const ready = !!file && (state.file === file || tributesLoaded.has(file));
  const tribute = ready ? (state.file === file ? state.tribute : tributesLoaded.get(file!) ?? null) : null;
  return { tribute, loading: !!entry && !ready };
};

// ---------------------------------------------------------------------------
// Helpers shared by Timeline / Commentary
// ---------------------------------------------------------------------------

/**
 * The latest season in the data (the owner's last coached season or Super Bowl), e.g. 80 for "Y80". Everything that
 * spans "Y1 to now" derives its end from this, so a season rollover needs no code change. 0 before content loads.
 */
export const latestSeasonYear = (content: LeagueContent | null | undefined): number => {
  const years = [...(content?.superBowls ?? []).map((s) => s.year), ...(content?.coach?.seasons ?? []).map((s) => s.year)];
  const fromLabel = Number(content?.season?.replace(/\D/g, '') ?? '');
  return years.length ? Math.max(...years) : Number.isFinite(fromLabel) ? fromLabel : 0;
};

/** Normalize a display name for lookup: drop parentheticals, quotes, punctuation. */
export const normalizeName = (name: string) =>
  name
    .replace(/\(.*?\)/g, '')
    .replace(/[’‘`']/g, '')
    .toLowerCase()
    .replace(/[^a-z0-9 ]+/g, ' ')
    .replace(/\s+/g, ' ')
    .trim();

/**
 * Find a player by an editorial name. Exact (normalized) match first, then
 * first+last name match ("Jackson W. Kline" -> "Jackson Wardell Kline"), then
 * the name inside parentheses ("God Johnson (Mason Earl III)").
 */
export const matchPlayerByName = <T extends { name: string }>(name: string, players: T[]): T | undefined => {
  // a "POS:Name" key (the NFL news tags players by ESPN id) picks that exact player, never a namesake at another position
  const key = /^([A-Z]{1,4}):(.+)$/.exec(name);
  if (key) {
    const hit = players.find((p) => p.name === key[2] && (p as unknown as { position?: string }).position === key[1]);
    if (hit) return hit;
    name = key[2];
  }
  const target = normalizeName(name);
  if (!target) return undefined;
  const exact = players.find((p) => normalizeName(p.name) === target);
  if (exact) return exact;
  const tParts = target.split(' ');
  if (tParts.length >= 2) {
    const loose = players.filter((p) => {
      const parts = normalizeName(p.name).split(' ');
      return parts.length >= 2 && parts[0] === tParts[0] && parts[parts.length - 1] === tParts[tParts.length - 1];
    });
    if (loose.length === 1) return loose[0];
  }
  const paren = name.match(/\((.+?)\)/)?.[1];
  if (paren && /^[A-Z]/.test(paren) && !/likely|final|formerly/i.test(paren)) {
    return matchPlayerByName(paren, players);
  }
  return undefined;
};

/** "Y61–64, Y66" style compression of a sorted year list. */
export const formatYearRuns = (years: number[]) => {
  const sorted = [...years].sort((a, b) => a - b);
  const runs: string[] = [];
  for (let i = 0; i < sorted.length; i++) {
    let j = i;
    while (j + 1 < sorted.length && sorted[j + 1] === sorted[j] + 1) j++;
    runs.push(j > i ? `${seasonLabel(sorted[i])}–${sorted[j]}` : `${seasonLabel(sorted[i])}`);
    i = j;
  }
  return runs.join(', ');
};

export interface FranchiseTitles {
  team: string;
  titles: number;
  losses: number;
  appearances: number;
  titleYears: number[];
}

/** Your franchise record in Super Bowls (titles desc). */
export const getFranchiseTitles = (superBowls: SuperBowlEntry[], range?: [number, number]): FranchiseTitles[] => {
  const map = new Map<string, FranchiseTitles>();
  for (const sb of superBowls) {
    if (!sb.yourTeam || (sb.yourResult !== 'won' && sb.yourResult !== 'lost')) continue;
    if (range && (sb.year < range[0] || sb.year > range[1])) continue;
    const row = map.get(sb.yourTeam) ?? { team: sb.yourTeam, titles: 0, losses: 0, appearances: 0, titleYears: [] };
    row.appearances++;
    if (sb.yourResult === 'won') {
      row.titles++;
      row.titleYears.push(sb.year);
    } else row.losses++;
    map.set(sb.yourTeam, row);
  }
  return [...map.values()].sort((a, b) => b.titles - a.titles || b.appearances - a.appearances || a.team.localeCompare(b.team));
};

/** League-wide champions (every winner), titles desc. */
export const getAllChampions = (superBowls: SuperBowlEntry[]) => {
  const map = new Map<string, { team: string; titles: number; titleYears: number[]; yours: number }>();
  for (const sb of superBowls) {
    if (!sb.winner) continue;
    const row = map.get(sb.winner) ?? { team: sb.winner, titles: 0, titleYears: [], yours: 0 };
    row.titles++;
    row.titleYears.push(sb.year);
    if (sb.yourResult === 'won') row.yours++;
    map.set(sb.winner, row);
  }
  return [...map.values()].sort((a, b) => b.titles - a.titles || a.team.localeCompare(b.team));
};
