import { useEffect, useMemo, useRef } from 'react';
import { Gauge, Search } from 'lucide-react';
import ScreensaverButton from './screensaver/ScreensaverButton';
import { NowPlayingPill } from './nowplaying/NowPlaying';
import { setPerfSetting, suggestLite, usePerfMode, type PerfSetting } from '@/hooks/usePerfMode';
import { cn } from '@/lib/utils';
import { openQuickSearch } from '@/utils/quickSearchEvent';
import { useLeague } from '@/context/LeagueContext';
import { useWarmPlayerSearch } from '@/utils/usePlayerSearch';
import { loadGameSprites } from '@/utils/gameSprites';
import { findNFLTeam } from '@/utils/nflTeams';
import { isHallOfFamer } from '@/config/stats';
import { useLeagueContent } from '@/utils/leagueContent';
import BrandMark from '@/components/brand/BrandMark';
import CountUp from '@/components/brand/CountUp';
import { reducedMotion } from '@/utils/motion';
import { usePhone } from '@/hooks/usePhone';

interface HeaderProps {
  activeTab: string;
  onTabChange: (tab: string) => void;
}

import { isKnownTab } from '@/components/stats/hub/hashRoute';
import { IS_NFL, NFL_HIDDEN_TABS, NFL_ONLY_TABS } from '@/config/edition';

const ALL_TABS = [
  ...(IS_NFL ? ([{ value: 'season', label: 'Season' }, { value: 'fantasy', label: 'Fantasy' }, { value: 'career', label: 'Stats' }, { value: 'games', label: 'Arcade' }] as const) : ([{ value: 'games', label: 'Arcade' }, { value: 'career', label: 'Stats' }, { value: 'season', label: 'Season' }] as const)),
  { value: 'college', label: 'College' },
  { value: 'lab', label: 'Team Lab' },
  ...(IS_NFL ? [] : ([{ value: 'fantasy', label: 'Fantasy' }] as const)),
  { value: 'hof', label: 'Hall of Fame' },
  { value: 'collection', label: 'Collection' },
  { value: 'timeline', label: 'Timeline' },
  { value: 'news', label: 'News' },
  { value: 'office', label: 'Front Office' },
] as const;
export const NAV_TABS = ALL_TABS.filter((t) => (IS_NFL ? !NFL_HIDDEN_TABS.includes(t.value) && (t.value !== 'college' || isKnownTab('college')) : !NFL_ONLY_TABS.includes(t.value)));

/** Header toggle for performance mode: cycles Auto → On → Off (persisted per viewer). */
const PerfToggle = () => {
  const { setting, lite } = usePerfMode();
  const next: Record<PerfSetting, PerfSetting> = { auto: 'on', on: 'off', off: 'auto' };
  const name = setting === 'auto' ? `Auto (${suggestLite() ? 'on' : 'off'})` : setting === 'on' ? 'On' : 'Off';
  return (
    <button
      type="button"
      onClick={() => setPerfSetting(next[setting])}
      aria-pressed={lite}
      aria-label={`Performance mode: ${name}. Turns off card tilt, shimmer, blur and long walkouts. Click to change.`}
      title={`Performance mode: ${name}`}
      className={cn(
        'inline-flex h-8 w-8 shrink-0 items-center justify-center rounded-md border transition-colors focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-gold',
        lite ? 'border-turf/70 text-turf' : 'border-line text-muted-foreground hover:border-gold/60 hover:text-foreground',
      )}
    >
      <Gauge className="h-3.5 w-3.5" aria-hidden="true" />
    </button>
  );
};

const Header = ({ activeTab, onTabChange }: HeaderProps) => {
  const { careerData, getAllPlayers, dataVersion } = useLeague();
  useWarmPlayerSearch();
  // the sprite index (core, then shards on demand) starts with the app, not with the first sprite that mounts
  useEffect(() => loadGameSprites(), []);
  const season = useLeagueContent().content?.season;
  const tabRefs = useRef<Record<string, HTMLButtonElement | null>>({});
  const headerRef = useRef<HTMLElement | null>(null);
  const headerH = useRef(0);

  // Publish the sticky header's live height so other sticky bars can sit right below it.
  useEffect(() => {
    const el = headerRef.current;
    if (!el || typeof ResizeObserver === 'undefined') return;
    const set = () => {
      headerH.current = el.offsetHeight;
      document.documentElement.style.setProperty('--site-header-h', `${el.offsetHeight}px`);
    };
    set();
    const ro = new ResizeObserver(set);
    ro.observe(el);
    return () => ro.disconnect();
  }, []);

  // Stats tab: slide the header (and the Stats sub-nav, see StatsHub) away while scrolling down, back on any scroll up.
  // Phones, every other tab: the same signal as 'down', which tucks only the bottom tab bar (BottomNav, .bnav).
  // CSS does the motion (.chrome-hide and .bnav in index.css; instant under reduced motion). Keyboard focus inside the
  // bars, the top of the page and a locked body (an open dialog) always bring them back.
  const phone = usePhone();
  useEffect(() => {
    const root = document.documentElement;
    const show = () => {
      if (root.dataset.chrome) delete root.dataset.chrome;
    };
    const hiddenAs = activeTab === 'career' ? 'hidden' : 'down';
    if (activeTab !== 'career' && !phone) {
      show();
      return;
    }
    let lastY = window.scrollY;
    let raf = 0;
    const check = () => {
      raf = 0;
      const y = window.scrollY;
      const dy = y - lastY;
      // Cached height and an inline-style check: no style or layout read per scroll frame
      const h = headerH.current || 64;
      const locked = document.body.hasAttribute('data-scroll-locked') || document.body.style.overflow === 'hidden';
      if (y <= h * 2 || locked) show();
      else if (dy > 8) {
        // Keep the bars while keyboard focus is inside one of them
        // (The tab bar only for keyboard focus: Android focuses a tapped tab, which must not pin the bar)
        const a = document.activeElement;
        const focusIn = a?.closest('[data-site-header], [data-chrome-bar]') || (a?.closest('.bnav') && a.matches(':focus-visible'));
        if (!focusIn && root.dataset.chrome !== hiddenAs) root.dataset.chrome = hiddenAs;
      } else if (dy < -8) show();
      if (Math.abs(dy) > 8 || y <= h * 2) lastY = y;
    };
    const onScroll = () => {
      if (!raf) raf = requestAnimationFrame(check);
    };
    const onFocus = (e: FocusEvent) => {
      const t = e.target as Element | null;
      if (t?.closest?.('[data-site-header], [data-chrome-bar]') || (t?.closest?.('.bnav') && t.matches(':focus-visible'))) show();
    };
    window.addEventListener('scroll', onScroll, { passive: true });
    document.addEventListener('focusin', onFocus);
    return () => {
      window.removeEventListener('scroll', onScroll);
      document.removeEventListener('focusin', onFocus);
      if (raf) cancelAnimationFrame(raf);
      show();
    };
  }, [activeTab, phone]);

  const board = useMemo(() => {
    const players = getAllPlayers();
    const teams = new Set<string>();
    players.forEach((p) => {
      const raw = p.team?.trim();
      if (!raw) return;
      teams.add(findNFLTeam(raw)?.id ?? raw.toLowerCase());
    });
    return {
      // Season tag ("Y80"): content.json derives it from the owner's last coached season
      season: season ?? null,
      players: players.length,
      teams: teams.size,
      hof: IS_NFL ? 0 : players.filter(isHallOfFamer).length,
      mvps: players.reduce((sum, p) => sum + (p.mvp || 0), 0),
      rings: players.reduce((sum, p) => sum + (p.rings || 0), 0),
    };
    // dataVersion bumps after edits/uploads so the board stays in sync
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [careerData, getAllPlayers, dataVersion, season]);

  // Keep the active tab visible in the scrollable mobile nav
  useEffect(() => {
    tabRefs.current[activeTab]?.scrollIntoView({ block: 'nearest', inline: 'center', behavior: reducedMotion() ? 'auto' : 'smooth' });
  }, [activeTab]);

  const nav = (
    <nav aria-label="Primary" className="min-w-0">
      {/* NFL edition: the tabs share the header's free width evenly (owner: "fit the empty space … equally spaced out") */}
      <ul className={cn('flex items-stretch gap-1 overflow-x-auto scrollbar-none -mx-1 px-1', IS_NFL && 'xl:justify-between xl:gap-2')}>
        {NAV_TABS.map((tab) => {
          const isActive = activeTab === tab.value;
          return (
            <li key={tab.value} className={cn('shrink-0', IS_NFL && 'xl:flex-1 xl:flex xl:justify-center')}>
              <button
                ref={(el) => (tabRefs.current[tab.value] = el)}
                type="button"
                onClick={() => onTabChange(tab.value)}
                aria-current={isActive ? 'page' : undefined}
                className={cn(
                  'relative h-11 px-3 sm:px-3.5 font-display text-[17px] font-bold uppercase tracking-wide whitespace-nowrap transition-colors',
                  // The underline grows out from the centre as a tab becomes active (transform only)
                  'after:absolute after:inset-x-2 after:bottom-0 after:h-[3px] after:rounded-t after:transition-[transform,background-color] after:duration-[var(--dur-3)] after:ease-[var(--ease-spring)]',
                  isActive
                    ? 'text-chalk after:scale-x-100 after:bg-gold'
                    : 'text-muted-foreground hover:text-chalk after:scale-x-0 after:bg-line hover:after:scale-x-100',
                )}
              >
                {tab.label}
              </button>
            </li>
          );
        })}
      </ul>
    </nav>
  );

  const lamps = careerData
    ? [
        { k: 'Players', v: board.players },
        { k: 'Teams', v: board.teams },
        ...(IS_NFL ? [{ k: 'MVPs', v: board.mvps }] : [{ k: 'HOF', v: board.hof }]),
        { k: 'Rings', v: board.rings },
      ]
    : [];

  return (
    <header ref={headerRef} data-site-header className="chrome-hide sticky top-0 z-50 border-b border-line/70 bg-night">
      <a
        href="#main"
        className="sr-only focus:not-sr-only focus:absolute focus:left-3 focus:top-3 focus:z-[60] focus:rounded focus:bg-gold focus:px-3 focus:py-2 focus:text-sm focus:font-semibold focus:text-primary-foreground"
      >
        Skip to content
      </a>

      {/* Gold rule across the top, like a broadcast bug */}
      <div className="h-[3px] bg-gradient-to-r from-gold via-gold/70 to-turf" aria-hidden="true" />

      <div className="container">
        <div className="flex items-center gap-3 sm:gap-4 lg:gap-5 min-[1440px]:gap-8 h-14 lg:h-16">
          <button
            type="button"
            onClick={() => onTabChange('career')}
            className="shrink-0 rounded-md"
            aria-label="Retro Vault home"
          >
            <BrandMark compact className="sm:hidden" />
            <BrandMark className="hidden sm:inline-flex" />
          </button>

          <div className="hidden lg:block flex-1 min-w-0 self-end">{nav}</div>

          {/* Search and the performance toggle: two small icons side by side */}
          <div className="ml-auto flex shrink-0 items-center gap-1.5 lg:ml-0">
            <button
              type="button"
              onClick={openQuickSearch}
              aria-label="Look up a player or club (Command K)"
              title="Search (⌘K)"
              className="inline-flex h-8 w-8 shrink-0 items-center justify-center rounded-md border border-line bg-night/60 max-sm:h-11 max-sm:w-11 text-muted-foreground transition-colors hover:border-gold/60 hover:text-foreground focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-gold"
            >
              <Search className="h-3.5 w-3.5 max-sm:h-4 max-sm:w-4" aria-hidden="true" />
            </button>

            {/* Phones: in the bottom bar's More sheet */}
            <span className="contents max-sm:hidden">
              <PerfToggle />
            </span>
          </div>

          {/* What is playing on Spotify, while connected and a song is on (phones: the strip above the tab bar) */}
          <NowPlayingPill />

          {/* The Season lamp; on a desktop it is also the screensaver's button */}
          {board.season && (
            <>
              <span className="lamp shrink-0 sm:hidden" aria-label={`Season ${board.season}`}>
                Season <b>{board.season}</b>
              </span>
              <ScreensaverButton season={board.season} />
            </>
          )}
        </div>

        {/* Tablet nav: horizontal scroll (phones use the bottom tab bar, BottomNav) */}
        <div className="-mt-1 max-sm:hidden lg:hidden">{nav}</div>
      </div>

      {/* Scoreboard strip */}
      {lamps.length > 0 && (
        <div className="scoreboard-strip max-sm:hidden">
          <div className="container">
            <p
              className="flex items-center gap-x-3 overflow-x-auto scrollbar-none py-1.5 font-pixel text-[10px] uppercase text-muted-foreground whitespace-nowrap"
              aria-label="League summary"
            >
              {lamps.map((l, i) => (
                <span key={l.k} className="inline-flex items-center gap-1.5">
                  {i > 0 && <span aria-hidden="true" className="text-line">·</span>}
                  <CountUp value={Number(l.v)} className="text-gold" />
                  <span>{l.k}</span>
                </span>
              ))}
              <span className="ml-auto pl-4 text-turf" aria-hidden="true">Ready</span>
            </p>
          </div>
        </div>
      )}
    </header>
  );
};

export default Header;
