import { createContext, startTransition, useCallback, useContext, useEffect, useLayoutEffect, useRef, useState } from 'react';
import { overlayOnTop } from '@/utils/overlayHistory';
import { IS_NFL } from '@/config/edition';

/**
 * Tiny hash router for the single-page hub. The URL hash mirrors the visible page so tabs are linkable
 * and the back button works:
 *
 *   #games                       top-level tab (games, stats, season, hof, collection, timeline, office)
 *   #stats/teams                 Stats sub-tab (players, teams, graphs, h2h, deepdive)
 *   #stats/players/leaders       ...plus a section id to scroll to inside the sub-tab
 *   #stats/deepdive?p=QB:Name    Player Deep Dive with a player preselected
 *   #stats/game?id=<game id>     One game in depth (NFL edition: box score, rosters, advanced stats)
 *   #stats/graphs?gx=ya&gy=intPct&pos=QB    Graph Builder on a shared chart (stats/graph/graphConfig);
 *                                            the old #stats/players?gx=… links land there too
 *   #season/club?c=Vikings&tab=franchise&y=2025   NFL edition: a club's page (overlay; tab = season | franchise)
 *   #lab?t=<lineup>              Team Lab with a lineup (utils/teamLab encodeLineup)
 *   #fantasy/<lineup|startsit|h2h|trade>   NFL edition: the Fantasy page (#fantasy/trade?p=WR:Name preloads a player on side one)
 *   #lab/trade and #lab?mode=fantasy      old links: they open the Fantasy page
 *
 * Old in-page anchors (#leaders, #head-to-head, #comp-finder, ...) and the retired #teams tab still resolve.
 * Unknown hashes are ignored (the current page stays), so plain in-page anchors keep working.
 */

export const STATS_SUBS = ['players', 'teams', 'graphs', 'h2h', 'deepdive', 'clock', 'game'] as const;
export type StatsSub = (typeof STATS_SUBS)[number];

/** Internal tab ids (as used by Header / Index) → hash names. */
const TAB_TO_HASH: Record<string, string> = { career: 'stats' };
const HASH_TO_TAB: Record<string, string> = { stats: 'career', arcade: 'games', teamlab: 'lab' };
const KNOWN_TABS = new Set(['games', 'career', 'season', 'lab', 'collection', ...(IS_NFL ? ['news', 'college', 'fantasy'] : ['hof', 'timeline', 'office']), ...(import.meta.env.DEV ? ['arcadekit', 'bannerlab'] : [])]);

/** Is this a top-level tab the router knows in this edition? (the nav hides entries whose route isn't there yet) */
export const isKnownTab = (tab: string): boolean => KNOWN_TABS.has(tab);

/** Legacy section anchors from the old one-page Stats layout → where they live now. */
const LEGACY_SECTIONS: Record<string, { sub: StatsSub; section?: string }> = {
  'record-book': { sub: 'players', section: 'record-book' },
  efficiency: { sub: 'players', section: 'efficiency' },
  leaders: { sub: 'players', section: 'leaders' },
  tables: { sub: 'players', section: 'tables' },
  analytics: { sub: 'players', section: 'analytics' },
  advanced: { sub: 'players', section: 'analytics' },
  'head-to-head': { sub: 'h2h' },
  'comp-finder': { sub: 'deepdive' },
};

export interface Route {
  tab: string;
  sub?: StatsSub;
  section?: string;
  /** Player key ("POS:Name") for Comps / Map deep links. */
  p?: string;
  /** Team Lab lineup (encodeLineup) */
  t?: string;
  /** Other Stats query params, e.g. the Graph Builder's gx / gy / pos (stats/graph/graphConfig GRAPH_PARAMS). */
  q?: Record<string, string>;
}

export const FANTASY_SUBS = ['lineup', 'startsit', 'h2h', 'trade'];
const isSub = (s: string | undefined): s is StatsSub => !!s && (STATS_SUBS as readonly string[]).includes(s);

export const parseHash = (hash: string): Route | null => {
  const raw = hash.replace(/^#\/?/, '');
  if (!raw) return null;
  const [path, query = ''] = raw.split('?');
  const segs = path.split('/').map((s) => {
    try {
      return decodeURIComponent(s);
    } catch {
      return s;
    }
  });
  const params = new URLSearchParams(query);
  const p = params.get('p') || undefined;
  const head = segs[0].toLowerCase();

  // #season/club?c=<Club>&tab=… is the club page overlay (ClubSeasonHost), never a page of its own: the page under it stays
  if (segs[1] === 'club' && params.get('c')) return null;

  if (head === 'teams') return { tab: 'career', sub: 'teams' };
  if (LEGACY_SECTIONS[head]) return { tab: 'career', ...LEGACY_SECTIONS[head] };

  const tab = HASH_TO_TAB[head] ?? head;
  if (!KNOWN_TABS.has(tab)) return null;
  if (tab === 'career') {
    const alias: Record<string, StatsSub> = { compare: 'h2h', comps: 'deepdive', 'deep-dive': 'deepdive', graph: 'graphs', 'graph-builder': 'graphs' };
    // The Analytics Lab now lives on the Players sub-tab
    if (segs[1] === 'advanced') return { tab, sub: 'players', section: 'analytics', p };
    const sub = isSub(segs[1]) ? segs[1] : alias[segs[1]];
    const q: Record<string, string> = {};
    params.forEach((v, k) => {
      if (k !== 'p') q[k] = v;
    });
    // Graph Builder links from before the Graphs tab (#stats/players?gx=…) open the Graphs tab.
    if (q.gx && q.gy && (!sub || sub === 'players')) return { tab, sub: 'graphs', q };
    return Object.keys(q).length ? { tab, sub, section: segs[2] || undefined, p, q } : { tab, sub, section: segs[2] || undefined, p };
  }
  if (tab === 'college') {
    // #college/<section>?y=2000 or ?s=<school slug> (the College tab's own state)
    const q: Record<string, string> = {};
    params.forEach((v, k) => {
      if (k !== 'p') q[k] = v;
    });
    return { tab, section: segs[1] || undefined, ...(Object.keys(q).length ? { q } : {}) };
  }
  const t = params.get('t') || undefined;
  if (tab === 'fantasy') return { tab, section: FANTASY_SUBS.includes(segs[1]) ? segs[1] : undefined, p };
  // old links: Team Lab's Trade and Fantasy modes moved to the Fantasy page
  if (IS_NFL && tab === 'lab' && segs[1] === 'trade') return { tab: 'fantasy', section: 'trade', p };
  if (IS_NFL && tab === 'lab' && params.get('mode') === 'fantasy') return { tab: 'fantasy', section: 'lineup' };
  if (IS_NFL && tab === 'lab' && params.get('mode') === 'trade') return { tab: 'fantasy', section: 'trade', p };
  return t ? { tab, p, t } : { tab, p };
};

export const buildHash = (r: Route): string => {
  let h = `#${TAB_TO_HASH[r.tab] ?? r.tab}`;
  if (r.tab === 'college' && r.section) h += `/${encodeURIComponent(r.section)}`;
  if (r.tab === 'career' && r.sub) {
    h += `/${r.sub}`;
    if (r.section) h += `/${encodeURIComponent(r.section)}`;
  }
  if (r.tab === 'fantasy' && r.section) h += `/${r.section}`;
  if (r.p) h += `?p=${encodeURIComponent(r.p)}`;
  if (r.t) h += `${r.p ? '&' : '?'}t=${encodeURIComponent(r.t).replace(/%20/g, '+')}`;
  if ((r.tab === 'career' || r.tab === 'college') && r.q) {
    const qs = new URLSearchParams(r.q).toString();
    if (qs) h += `${h.includes('?') ? '&' : '?'}${qs}`;
  }
  return h;
};

const sameRoute = (a: Route, b: Route) => buildHash(a) === buildHash(b);

/*
 * Scroll position per page, like a native app: a page you go to opens at its top, at once (no visible scroll travel);
 * Back and Forward put each page back where you left it. The browser's own restoration is off (it restores before
 * a lazy page has its height, then the page jumps). Each history entry carries an id in history.state ({ rv }), and
 * the scroll position is saved under it when you leave.
 */
type NavKind = 'push' | 'pop' | 'replace' | 'init';
let navKind: NavKind = 'init';
/** How the latest route change came about (views use it: a sub-tab change from Back must not scroll itself). */
export const lastNavKind = () => navKind;
const saved = new Map<number, number>();
let entrySeq = 0;
const entryId = (): number => {
  const st = window.history.state as { rv?: number } | null;
  if (st && typeof st.rv === 'number') {
    entrySeq = Math.max(entrySeq, st.rv);
    return st.rv;
  }
  const id = ++entrySeq;
  window.history.replaceState({ ...(st ?? {}), rv: id }, '');
  return id;
};
/** The first entry this page load made or found: anything above it is an in-app page Back can return to */
let firstEntry = 0;
/** Is there an earlier page of this app in the history (so Back stays in the app)? */
export const canGoBackInApp = () => {
  const st = typeof window === 'undefined' ? null : (window.history.state as { rv?: number } | null);
  return !!st && typeof st.rv === 'number' && firstEntry > 0 && st.rv > firstEntry;
};
/** Jump with no smooth travel, whatever the stylesheet says */
const jump = (y: number) => window.scrollTo({ top: y, left: 0, behavior: 'instant' as ScrollBehavior });

/**
 * The current route, kept in sync with the URL hash. `navigate` pushes a history entry (or replaces with
 * `{ replace: true }`). Re-navigating to the Stats tab without a sub-tab returns to the last one used.
 *
 * Route changes render as a transition: the old page stays up (and responsive) while the new one renders or its
 * lazy chunk loads, so a fast switch never flashes a skeleton and a slow one never blocks the tap. `target` is the
 * route being switched to, updated at once, for the nav highlights. Replacements (a view syncing its own state to the
 * URL) apply at once.
 *
 * Scroll: a new top-level page starts at its top, set in the same commit that shows it (before the paint); within the
 * Stats tab the hub keeps its own rule (StatsHub: back to the panel's top). Back / Forward restore the saved position,
 * following a lazy page as it grows until it is tall enough (or the reader scrolls).
 */
export const useHashRoute = (defaultTab = 'games') => {
  const lastSub = useRef<StatsSub>('players');
  const read = useCallback((): Route => {
    const r = typeof window === 'undefined' ? null : parseHash(window.location.hash);
    return r ?? { tab: defaultTab };
  }, [defaultTab]);
  const [route, setRoute] = useState<Route>(() => {
    const r = read();
    return r.tab === 'career' && !r.sub ? { ...r, sub: 'players' } : r;
  });
  const [target, setTarget] = useState<Route>(route);
  if (route.sub) lastSub.current = route.sub;
  // The latest route asked for (ahead of `route` while a transition is pending)
  const targetRef = useRef(route);
  // The history entry on screen, and what to do with the scroll once the next route commits
  const current = useRef(0);
  const pendingScroll = useRef<{ kind: 'top' | 'restore'; y: number } | null>(null);
  const show = useCallback((next: Route, urgent = false) => {
    targetRef.current = next;
    setTarget(next);
    if (urgent) setRoute(next);
    else startTransition(() => setRoute(next));
  }, []);

  useEffect(() => {
    try {
      window.history.scrollRestoration = 'manual';
    } catch {
      /* not supported */
    }
    current.current = entryId();
    if (!firstEntry) firstEntry = current.current;
  }, []);

  useEffect(() => {
    const sync = () => {
      // popstate and hashchange both fire for one Back: only the first one counts
      const id = entryId();
      const entered = id !== current.current;
      if (entered) {
        saved.set(current.current, window.scrollY);
        current.current = id;
      }
      const r = parseHash(window.location.hash);
      if (!r) return; // plain anchor: stay where we are (the browser jumps to it)
      const next = r.tab === 'career' && !r.sub ? { ...r, sub: lastSub.current } : r;
      if (sameRoute(next, targetRef.current)) return;
      if (entered) {
        const y = saved.get(id);
        navKind = 'pop';
        pendingScroll.current = y != null ? { kind: 'restore', y } : { kind: 'top', y: 0 };
      }
      show(next);
    };
    window.addEventListener('popstate', sync);
    window.addEventListener('hashchange', sync);
    return () => {
      window.removeEventListener('popstate', sync);
      window.removeEventListener('hashchange', sync);
    };
  }, [show]);

  const navigate = useCallback((to: Route, opts?: { replace?: boolean }) => {
    const next: Route = to.tab === 'career' && !to.sub ? { ...to, sub: lastSub.current } : to;
    const hash = buildHash(next);
    const changed = !sameRoute(next, targetRef.current);
    if (hash !== window.location.hash) {
      if (opts?.replace) {
        // A replacement made from inside an overlay (a Deep Dive pick in the skill leaderboard sheet or the search
        // sheet) takes the overlay's entry over: drop its `ov` mark, so the overlay closing does not pop the new route
        // (owner: picking a player "just reloads the current player")
        const st = (window.history.state ?? {}) as Record<string, unknown>;
        if ('ov' in st) {
          const rest = { ...st };
          delete rest.ov;
          window.history.replaceState(rest, '', hash);
        } else window.history.replaceState(st, '', hash);
      } else {
        saved.set(current.current, window.scrollY);
        const id = ++entrySeq;
        // An open overlay's entry (utils/overlayHistory) is replaced, not stacked on: Back from the new page returns to
        // the page under the overlay, never to a duplicate of it
        if (overlayOnTop()) window.history.replaceState({ rv: id }, '', hash);
        else window.history.pushState({ rv: id }, '', hash);
        current.current = id;
      }
    }
    if (next.sub) lastSub.current = next.sub;
    if (changed) {
      navKind = opts?.replace ? 'replace' : 'push';
      // A new top-level page opens at its top (sections and Stats sub-tabs place themselves)
      pendingScroll.current = !opts?.replace && next.tab !== targetRef.current.tab ? { kind: 'top', y: 0 } : null;
    }
    // Replacements keep a view's own state in the URL (a chart, the Deep Dive player, a section): those stay urgent
    if (changed) show(next, !!opts?.replace);
  }, [show]);

  // Apply the scroll in the commit that shows the new route, before it paints
  const routeHash = buildHash(route);
  useLayoutEffect(() => {
    const want = pendingScroll.current;
    if (!want || buildHash(targetRef.current) !== routeHash) return;
    pendingScroll.current = null;
    jump(want.y);
    if (want.kind !== 'restore' || Math.abs(window.scrollY - want.y) < 2) return;
    // The page is still short (lazy parts loading): follow it as it grows, until it fits, the reader scrolls, or 2 s
    let done = false;
    const stop = () => {
      if (done) return;
      done = true;
      ro?.disconnect();
      window.clearTimeout(timer);
      ['wheel', 'touchstart', 'keydown'].forEach((t) => window.removeEventListener(t, stop));
    };
    const ro = typeof ResizeObserver !== 'undefined' ? new ResizeObserver(() => {
      jump(want.y);
      if (Math.abs(window.scrollY - want.y) < 2) stop();
    }) : null;
    ro?.observe(document.body);
    const timer = window.setTimeout(stop, 2000);
    ['wheel', 'touchstart', 'keydown'].forEach((t) => window.addEventListener(t, stop, { passive: true }));
    return stop;
  }, [routeHash]);

  return { route, target, navigate };
};

export type Navigate = (to: Route, opts?: { replace?: boolean }) => void;

/** Route + navigate for pages under Index (Stats hub, Map). Index provides it. */
export const HubRouteContext = createContext<{ route: Route; target?: Route; navigate: Navigate }>({
  route: { tab: 'games' },
  navigate: () => undefined,
});

export const useHubRoute = () => useContext(HubRouteContext);
